  describe('Session Management', () => {
    it('should maintain authentication state across page reloads', () => {
      // Simulate authentication
      const mockToken =
        btoa(
          JSON.stringify({
            header: { alg: 'HS256', typ: 'JWT' },
          })
        ) +
        '.' +
        btoa(
          JSON.stringify({
