        TestBed.inject(ConfigService),
        TestBed.inject(Router)
      );

      expect(newAuthService.isAuthenticated()).toBe(true);
    });

    it('should handle token expiration gracefully', () => {
      // Set up expired token
      const expiredToken =
        btoa(
          JSON.stringify({
            header: { alg: 'HS256', typ: 'JWT' },
          })
        ) +
        '.' +
        btoa(
          JSON.stringify({
            exp: Math.floor(Date.now() / 1000) - 3600, // Expired 1 hour ago
          })
        ) +
        '.signature';

      localStorage.setItem('auth_token', expiredToken);
      localStorage.setItem(
        'currentUser',
        JSON.stringify({
          token: expiredToken,
          email: 'test@example.com',
          firstName: 'John',
          lastName: 'Doe',
        })
      );

      // Check authentication - should be false due to expired token
      expect(authService.isAuthenticated()).toBe(false);
      expect(localStorage.getItem('auth_token')).toBe(null);
    });

    it('should complete logout workflow', async () => {
      // Set up authenticated state
      const mockToken =
        btoa(
          JSON.stringify({
            header: { alg: 'HS256', typ: 'JWT' },
          })
        ) +
        '.' +
        btoa(
          JSON.stringify({
            exp: Math.floor(Date.now() / 1000) + 3600,
          })
        ) +
        '.signature';

      localStorage.setItem('auth_token', mockToken);
      localStorage.setItem(
        'currentUser',
        JSON.stringify({
          token: mockToken,
          email: 'test@example.com',
          firstName: 'John',
          lastName: 'Doe',
        })
      );

      expect(authService.isAuthenticated()).toBe(true);

      // Logout
      authService.logout();

      // Verify cleanup
      expect(authService.isAuthenticated()).toBe(false);
      expect(localStorage.getItem('auth_token')).toBe(null);
      expect(localStorage.getItem('currentUser')).toBe(null);
      expect(location.path()).toBe('/login');
