      readAsText: jasmine.createSpy('readAsText').and.callFake(function(file: File) {
        setTimeout(() => {
          if (this.onload) {
            this.onload({ target: { result } });
          }
        }, 0);
      }),
      onload: null as any,
      onerror: null as any,
      onabort: null as any,
      onloadstart: null as any,
      onloadend: null as any,
      onprogress: null as any,
      readyState: 0,
      result: null,
      error: null
    };
    return reader as any;
