      }));

      replicateService.getPredictionStatus.and.returnValue(of({
        success: true,
        data: {
          status: 'succeeded',
          output: ['https://enhanced-image.jpg']
        }
      }));

      await component.startEnhancement();

      expect(stateService.setState).toHaveBeenCalledWith({
        creditsInfo: {
          availableCredits: 5,
          availableCredits: 4
        }
      });
