import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, map, Observable, tap } from 'rxjs';
import { Router } from '@angular/router';
import { ConfigService } from './config.service';

export interface LoginDto {
  email: string;
  password: string;
}

export interface RegisterDto {
  email: string;
  password: string;
  firstName: string;
  lastName: string;
  gender: string;
  ethnicity: string;
}

export interface AuthResponseDto {
  token: string;
  email: string;
  firstName: string;
  lastName: string;
}

export interface ApiAuthResponseDto {
  isSuccess: boolean;
  message: string;
  token: string;
  expiration: string;
  email?: string;
  firstName?: string;
  lastName?: string;
}

@Injectable({
  providedIn: 'root',
})
export class AuthService {
  private readonly TOKEN_KEY = 'auth_token';

  private _isAuthenticatedSubject = new BehaviorSubject<boolean>(this.hasToken());
  public isAuthenticated$ = this._isAuthenticatedSubject.asObservable();

  private _currentUserSubject = new BehaviorSubject<AuthResponseDto | null>(this.getCurrentUser());
  public currentUser$ = this._currentUserSubject.asObservable();

  constructor(
    private _http: HttpClient,
    private _config: ConfigService,
    private _router: Router
  ) {
    // Initialize with secure session check
    this.initializeSecureAuth();
  }

  /**
   * Initialize secure authentication with improved session management
   */
  private initializeSecureAuth(): void {
    // Check existing token validity
    this.checkTokenValidity();

    // Set up periodic token validation (reduced frequency for better performance)
    setInterval(
      () => {
        if (localStorage.getItem(this.TOKEN_KEY)) {
          this.checkTokenValidity();
        }
      },
      10 * 60 * 1000
    ); // Check every 10 minutes instead of 5
  }

  /**
   * Enhanced token validity check with better error handling
   */
  private checkTokenValidity(): void {
    const token = localStorage.getItem(this.TOKEN_KEY);
    if (!token) {
      return;
    }

    try {
      if (this.isTokenExpired(token)) {
        console.warn('🔒 Token expired, initiating secure logout');
        this.secureLogout('token_expired');
      }
    } catch (error) {
      console.error('🔒 Token validation error:', error);
      this.secureLogout('token_invalid');
    }
  }

  handleOAuthCallback(token: string, expiration?: string): void {
    if (token) {
      try {
        // Store the token using consistent key
        localStorage.setItem(this.TOKEN_KEY, token);
        localStorage.setItem('authToken', token); // Keep both for compatibility

        if (expiration) {
          localStorage.setItem('tokenExpiration', expiration);
        }

        // Extract user info from token
        const user = this.extractUserFromToken(token);

        if (user && user.firstName && user.lastName) {
          // Complete user data from JWT
          localStorage.setItem('currentUser', JSON.stringify(user));
          this._currentUserSubject.next(user);
          this._isAuthenticatedSubject.next(true);
        } else {
          // Incomplete JWT data, fetch from profile API
          this._isAuthenticatedSubject.next(true);

          // Fetch user profile data from API to get complete firstName/lastName
          this.fetchUserProfileForOAuth(token);
        }
      } catch (error) {
        console.error('Error in OAuth callback handling:', error);
        this._isAuthenticatedSubject.next(false);
      }
    }
  }

  private fetchUserProfileForOAuth(token: string): void {
    // Create a minimal user object with just email for now
    const payload = JSON.parse(atob(token.split('.')[1]));
    const email =
      payload['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress'] ||
      payload['email'] ||
      '';

    // Temporary user object while we fetch profile
    const tempUser = {
      token,
      email,
      firstName: '',
      lastName: '',
    };

    localStorage.setItem('currentUser', JSON.stringify(tempUser));
    this._currentUserSubject.next(tempUser);

    // Fetch user profile from API to get firstName/lastName
    this._http.get<{ firstName?: string; lastName?: string; email?: string }>(`${this._config.baseUrl}/profile`).subscribe({
      next: response => {
        // Handle response that contains data directly (not wrapped in success/data structure)
        if (response && (response.firstName || response.lastName)) {
          const completeUser = {
            token,
            email,
            firstName: response.firstName || '',
            lastName: response.lastName || '',
          };

          localStorage.setItem('currentUser', JSON.stringify(completeUser));
          this._currentUserSubject.next(completeUser);
        } else {
          // Keep the temp user with email username as firstName
          const fallbackUser = {
            ...tempUser,
            firstName: email.split('@')[0],
          };
          localStorage.setItem('currentUser', JSON.stringify(fallbackUser));
          this._currentUserSubject.next(fallbackUser);
        }
      },
      error: error => {
        console.error('Failed to fetch user profile:', error);
        // Fallback to email username
        const fallbackUser = {
          ...tempUser,
          firstName: email.split('@')[0],
        };
        localStorage.setItem('currentUser', JSON.stringify(fallbackUser));
        this._currentUserSubject.next(fallbackUser);
      },
    });
  }

  private extractUserFromToken(token: string): AuthResponseDto | null {
    try {
      const payload = JSON.parse(atob(token.split('.')[1]));
      // Remove sensitive payload logging in production

      // Check .NET ClaimTypes standard URIs first, then fallback to short names
      const email =
        payload['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress'] ||
        payload['email'] ||
        '';

      const firstName =
        payload['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/givenname'] ||
        payload['given_name'] ||
        payload['givenname'] ||
        payload['firstName'] ||
        '';

      const lastName =
        payload['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/surname'] ||
        payload['family_name'] ||
        payload['surname'] ||
        payload['lastName'] ||
        '';

      // If no firstName/lastName in JWT, return null to force profile API lookup
      if (!firstName && !lastName) {
        console.log('🔒 JWT missing user details, fetching from profile API');
        return null;
      }

      return {
        token,
        email,
        firstName,
        lastName,
      };
    } catch (error) {
      console.error('Failed to extract user from token:', error);
      return null;
    }
  }

  login(credentials: LoginDto): Observable<AuthResponseDto> {
    return this._http.post<ApiAuthResponseDto>(this._config.authLoginUrl, credentials).pipe(
      map(apiResponse => {
        if (!apiResponse.isSuccess) {
          throw new Error(apiResponse.message);
        }
        // Use API response data directly (firstName/lastName come from the API response, not JWT)
        const authResponse = {
          token: apiResponse.token,
          email: apiResponse.email || '',
          firstName: apiResponse.firstName || '',
          lastName: apiResponse.lastName || '',
        } as AuthResponseDto;
        return authResponse;
      }),
      tap(response => this.setSecureSession(response))
    );
  }

  register(userData: RegisterDto): Observable<AuthResponseDto> {
    return this._http.post<ApiAuthResponseDto>(this._config.authRegisterUrl, userData).pipe(
      map(apiResponse => {
        if (!apiResponse.isSuccess) {
          throw new Error(apiResponse.message);
        }
        return {
          token: apiResponse.token,
          email: apiResponse.email || '',
          firstName: apiResponse.firstName || '',
          lastName: apiResponse.lastName || '',
        } as AuthResponseDto;
      }),
      tap(response => this.setSecureSession(response))
    );
  }

  /**
   * Enhanced logout with secure session cleanup
   */
  logout(): void {
    this.secureLogout('user_initiated');
  }

  /**
   * Secure logout with reason tracking and proper cleanup
   */
  private secureLogout(reason: string): void {
    console.log(`🔒 Secure logout initiated - reason: ${reason}`);

    try {
      // Clear all authentication data securely
      this.clearAllAuthData();

      // Update reactive state
      this._isAuthenticatedSubject.next(false);
      this._currentUserSubject.next(null);

      // Navigate to login with reason
      this.navigateToLogin(reason);

      console.log('🔒 Secure logout completed successfully');
    } catch (error) {
      console.error('🔒 Error during secure logout:', error);
      // Force clear even if error occurs
      localStorage.clear();
      this._router.navigate(['/auth/login']);
    }
  }

  /**
   * Clear all authentication-related data
   */
  private clearAllAuthData(): void {
    const authKeys = [
      this.TOKEN_KEY,
      'authToken',
      'tokenExpiration',
      'current_user',
      'currentUser',
      'token',
      'user',
      'auth',
      'secure_session',
      'refresh_token',
    ];

    authKeys.forEach(key => {
      localStorage.removeItem(key);
    });
  }

  /**
   * Navigate to login page with logout reason
   */
  private navigateToLogin(reason: string): void {
    const queryParams = reason !== 'user_initiated' ? { reason } : {};

    this._router.navigate(['/auth/login'], { queryParams }).then(success => {
      if (success) {
        console.log('✅ Successfully navigated to login page');
      } else {
        console.error('❌ Failed to navigate to login page');
        // Fallback - force page reload to login
        window.location.href = '/auth/login';
      }
    });
  }

  /**
   * Force logout - clears all auth data (useful for debugging)
   */
  forceLogout(): void {
    console.log('🔒 Force logout initiated');
    try {
      localStorage.clear();
      this._isAuthenticatedSubject.next(false);
      this._currentUserSubject.next(null);
      this._router.navigate(['/auth/login']);
      console.log('🔒 Force logout completed');
    } catch (error) {
      console.error('🔒 Error during force logout:', error);
      // Force page reload as fallback
      window.location.href = '/auth/login';
    }
  }

  getToken(): string | null {
    return localStorage.getItem(this.TOKEN_KEY);
  }

  isAuthenticated(): boolean {
    return this.hasToken();
  }

  getCurrentUserId(): string | null {
    const token = this.getToken();
    if (!token) {
      return null;
    }

    try {
      const payload = JSON.parse(atob(token.split('.')[1]));
      // .NET Identity uses 'nameid' claim for NameIdentifier
      const userId =
        payload.nameid ||
        payload['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier'] ||
        payload.sub ||
        payload.userId;
      return userId || null;
    } catch (error) {
      console.error('🔒 Failed to extract user ID from token:', error);
      return null;
    }
  }

  /**
   * Set session with enhanced security
   */
  private setSecureSession(authResult: AuthResponseDto): void {
    try {
      // Store token and user data
      localStorage.setItem(this.TOKEN_KEY, authResult.token);
      localStorage.setItem('currentUser', JSON.stringify(authResult));

      // Clean up old storage keys for security
      localStorage.removeItem('current_user');
      localStorage.removeItem('authData'); // Remove any legacy keys

      // Update reactive state
      this._isAuthenticatedSubject.next(true);
      this._currentUserSubject.next(authResult);

      console.log('🔒 Secure session established successfully');
    } catch (error) {
      console.error('🔒 Failed to establish secure session:', error);
      throw new Error('Session establishment failed');
    }
  }

  private setSession(authResult: AuthResponseDto): void {
    // Deprecated - use setSecureSession instead
    this.setSecureSession(authResult);
  }

  private hasToken(): boolean {
    const token = localStorage.getItem(this.TOKEN_KEY);

    if (!token) {
      return false;
    }

    const isExpired = this.isTokenExpired(token);

    if (isExpired) {
      console.warn('🔒 Auth token has expired');
      this.logout();
      return false;
    }

    return true;
  }

  private getCurrentUser(): AuthResponseDto | null {
    // Try both storage keys for backwards compatibility
    let userStr = localStorage.getItem('currentUser');
    if (!userStr) {
      userStr = localStorage.getItem('current_user');
    }

    if (userStr) {
      try {
        return JSON.parse(userStr);
      } catch {
        return null;
      }
    }

    return null;
  }

  private isTokenExpired(token: string): boolean {
    try {
      const payload = JSON.parse(atob(token.split('.')[1]));
      const exp = payload.exp * 1000; // Convert to milliseconds
      return Date.now() >= exp;
    } catch (error) {
      return true; // If we can't parse the token, consider it expired
    }
  }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpErrorResponse, HttpHeaders } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError, map } from 'rxjs/operators';
import { ConfigService } from './config.service';

/**
 * Standard API response format used throughout the application
 */
export interface ApiResponse<T = any> {
  success: boolean;
  data?: T;
  message?: string;
  error?: {
    code: string;
    message: string;
  };
}

/**
 * Configuration options for HTTP requests
 */
export interface RequestOptions {
  headers?: HttpHeaders | Record<string, string | string[]>;
  withCredentials?: boolean;
  observe?: 'body';
  responseType?: 'json';
  reportProgress?: boolean;
}

/**
 * Base HTTP service that provides common HTTP patterns and error handling
 */
@Injectable({
  providedIn: 'root',
})
export class BaseHttpService {
  constructor(
    protected http: HttpClient,
    protected config: ConfigService
  ) {}

  /**
   * Builds a full API URL from a relative path
   */
  protected buildApiUrl(endpoint: string): string {
    const baseUrl = this.config.getApiUrl();
    const cleanEndpoint = endpoint.startsWith('/') ? endpoint.slice(1) : endpoint;
    return `${baseUrl}/${cleanEndpoint}`;
  }

  /**
   * Builds a full URL (for external resources or specific base URLs)
   */
  protected buildFullUrl(baseUrl: string, endpoint: string): string {
    const cleanBase = baseUrl.endsWith('/') ? baseUrl.slice(0, -1) : baseUrl;
    const cleanEndpoint = endpoint.startsWith('/') ? endpoint.slice(1) : endpoint;
    return `${cleanBase}/${cleanEndpoint}`;
  }

  /**
   * GET request with standardized error handling and response mapping
   */
  protected get<T>(endpoint: string, options?: RequestOptions): Observable<T> {
    const url = this.buildApiUrl(endpoint);
    return this.http.get<ApiResponse<T>>(url, options).pipe(
      map(response => this.extractData<T>(response)),
      catchError(error => this.handleError(error, 'GET', endpoint))
    );
  }

  /**
   * POST request with standardized error handling and response mapping
   */
  protected post<T>(endpoint: string, body: any, options?: RequestOptions): Observable<T> {
    const url = this.buildApiUrl(endpoint);
    return this.http.post<ApiResponse<T>>(url, body, options).pipe(
      map(response => this.extractData<T>(response)),
      catchError(error => this.handleError(error, 'POST', endpoint))
    );
  }

  /**
   * PUT request with standardized error handling and response mapping
   */
  protected put<T>(endpoint: string, body: any, options?: RequestOptions): Observable<T> {
    const url = this.buildApiUrl(endpoint);
    return this.http.put<ApiResponse<T>>(url, body, options).pipe(
      map(response => this.extractData<T>(response)),
      catchError(error => this.handleError(error, 'PUT', endpoint))
    );
  }

  /**
   * DELETE request with standardized error handling and response mapping
   */
  protected delete<T>(endpoint: string, options?: RequestOptions): Observable<T> {
    const url = this.buildApiUrl(endpoint);
    return this.http.delete<ApiResponse<T>>(url, options).pipe(
      map(response => this.extractData<T>(response)),
      catchError(error => this.handleError(error, 'DELETE', endpoint))
    );
  }

  /**
   * PATCH request with standardized error handling and response mapping
   */
  protected patch<T>(endpoint: string, body: any, options?: RequestOptions): Observable<T> {
    const url = this.buildApiUrl(endpoint);
    return this.http.patch<ApiResponse<T>>(url, body, options).pipe(
      map(response => this.extractData<T>(response)),
      catchError(error => this.handleError(error, 'PATCH', endpoint))
    );
  }

  /**
   * Raw HTTP request without response mapping (for non-standard APIs)
   */
  protected rawGet<T>(url: string, options?: RequestOptions): Observable<T> {
    return this.http
      .get<T>(url, options)
      .pipe(catchError(error => this.handleError(error, 'GET', url)));
  }

  /**
   * Raw POST request without response mapping (for non-standard APIs)
   */
  protected rawPost<T>(url: string, body: any, options?: RequestOptions): Observable<T> {
    return this.http
      .post<T>(url, body, options)
      .pipe(catchError(error => this.handleError(error, 'POST', url)));
  }

  /**
   * Extracts data from standard API response format
   */
  private extractData<T>(response: ApiResponse<T>): T {
    if (response.success && response.data !== undefined) {
      return response.data;
    }

    if (!response.success && response.error) {
      throw new Error(`API Error: ${response.error.code} - ${response.error.message}`);
    }

    // Handle cases where success is true but no data field exists
    // (e.g., delete operations that return { success: true, message: "..." })
    if (response.success) {
      return response as any; // Return the whole response for backward compatibility
    }

    throw new Error('Unexpected API response format');
  }

  /**
   * Standardized error handling for HTTP requests
   */
  private handleError(
    error: HttpErrorResponse,
    method: string,
    endpoint: string
  ): Observable<never> {
    let errorMessage = 'An unknown error occurred';
    let errorCode = 'UnknownError';

    if (error.error instanceof ErrorEvent) {
      // Client-side error
      errorMessage = `Client Error: ${error.error.message}`;
      errorCode = 'ClientError';
    } else {
      // Server-side error
      if (error.error && typeof error.error === 'object') {
        // API error response
        if (error.error.error) {
          errorMessage = error.error.error.message || errorMessage;
          errorCode = error.error.error.code || 'ServerError';
        } else if (error.error.message) {
          errorMessage = error.error.message;
          errorCode = 'ServerError';
        }
      } else {
        // HTTP error
        errorMessage = `HTTP ${error.status}: ${error.statusText || 'Unknown Error'}`;
        errorCode = `HTTP${error.status}`;
      }
    }

    // Log error for debugging
    console.error(`HTTP ${method} ${endpoint} failed:`, {
      code: errorCode,
      message: errorMessage,
      status: error.status,
      url: error.url,
      originalError: error,
    });

    return throwError(() => ({
      code: errorCode,
      message: errorMessage,
      status: error.status,
      originalError: error,
    }));
  }

  /**
   * Creates standard HTTP headers with authentication if available
   */
  protected createAuthHeaders(): HttpHeaders {
    let headers = new HttpHeaders({
      'Content-Type': 'application/json',
    });

    const token = localStorage.getItem('auth_token');
    if (token) {
      headers = headers.set('Authorization', `Bearer ${token}`);
    }

    return headers;
  }

  /**
   * Creates HTTP headers for file uploads
   */
  protected createUploadHeaders(): HttpHeaders {
    let headers = new HttpHeaders();
    // Don't set Content-Type for file uploads - let browser set it with boundary

    const token = localStorage.getItem('auth_token');
    if (token) {
      headers = headers.set('Authorization', `Bearer ${token}`);
    }

    return headers;
  }

  /**
   * Utility method to check if user is authenticated
   */
  protected isAuthenticated(): boolean {
    return !!localStorage.getItem('auth_token');
  }
}

