    });
  });
});

import { Injectable } from '@angular/core';
import { CacheEntry, CacheStats, ICacheManagerService } from '../interfaces/service.interfaces';

@Injectable({
  providedIn: 'root',
})
export class CacheManagerService implements ICacheManagerService {
  private cache = new Map<string, CacheEntry<any>>();
  private lastRequestTimes = new Map<string, number>();

  // Cache duration constants
  static readonly DASHBOARD_CACHE_DURATION_MS = 30000; // 30 seconds
  static readonly HTTP_CACHE_DURATION_MS = 60000; // 60 seconds
  static readonly LOAD_DEBOUNCE_MS = 1000; // 1 second

  constructor() {}

  /**
   * Check if cached data is still valid
   */
  isCacheValid(cacheKey: string): boolean {
    const now = Date.now();
    const cacheEntry = this.cache.get(cacheKey);

    if (!cacheEntry) {
      return false;
    }

    const isValid = now < cacheEntry.expiry;

    if (isValid) {
      // Update last accessed time
      cacheEntry.lastAccessed = now;
    } else {
      // Remove expired cache entry
      this.cache.delete(cacheKey);
    }

    return isValid;
  }

  /**
   * Get cached data if valid
   */
  getCachedData<T>(cacheKey: string): T | null {
    if (this.isCacheValid(cacheKey)) {
      const cacheEntry = this.cache.get(cacheKey);
      return cacheEntry ? cacheEntry.data : null;
    }
    return null;
  }

  /**
   * Set data in cache with expiry
   */
  setCachedData<T>(cacheKey: string, data: T, durationMs: number): void {
    const now = Date.now();
    const cacheEntry: CacheEntry<T> = {
      data,
      expiry: now + durationMs,
      lastAccessed: now,
    };

    this.cache.set(cacheKey, cacheEntry);

    // Clean up old cache entries periodically
    this.cleanupExpiredEntries();
  }

  /**
   * Invalidate specific cache entry
   */
  invalidateCache(cacheKey: string): void {
    if (this.cache.has(cacheKey)) {
      this.cache.delete(cacheKey);
    }
  }

  /**
   * Invalidate all cache entries
   */
  invalidateAllCache(): void {
    this.cache.clear();
    this.lastRequestTimes.clear();
  }

  /**
   * Check if request should be debounced
   */
  shouldDebounceRequest(requestKey: string, debounceMs: number): boolean {
    const now = Date.now();
    const lastRequestTime = this.lastRequestTimes.get(requestKey);

    if (lastRequestTime && now - lastRequestTime < debounceMs) {
      return true;
    }

    this.lastRequestTimes.set(requestKey, now);
    return false;
  }

  /**
   * Force refresh by clearing cache and request times
   */
  forceRefresh(cacheKey?: string): void {
    if (cacheKey) {
      this.invalidateCache(cacheKey);
      this.lastRequestTimes.delete(cacheKey);
    } else {
      this.invalidateAllCache();
    }
  }

  /**
   * Get cache statistics for debugging
   */
  getCacheStats(): {
    totalEntries: number;
    validEntries: number;
    expiredEntries: number;
    cacheHitRatio: number;
  } {
    const now = Date.now();
    let validEntries = 0;
    let expiredEntries = 0;

    for (const [key, entry] of this.cache.entries()) {
      if (now < entry.expiry) {
        validEntries++;
      } else {
        expiredEntries++;
      }
    }

    const totalRequests = this.lastRequestTimes.size;
    const cacheHitRatio = totalRequests > 0 ? (validEntries / totalRequests) * 100 : 0;

    return {
      totalEntries: this.cache.size,
      validEntries,
      expiredEntries,
      cacheHitRatio: Math.round(cacheHitRatio * 100) / 100,
    };
  }

  /**
   * Clean up expired cache entries
   */
  private cleanupExpiredEntries(): void {
    const now = Date.now();
    let cleanedCount = 0;

    for (const [key, entry] of this.cache.entries()) {
      if (now >= entry.expiry) {
        this.cache.delete(key);
        cleanedCount++;
      }
    }

    // Silently clean up expired entries
  }
}

import { Injectable } from '@angular/core';
import { environment } from '../../environments/environment';

@Injectable({
  providedIn: 'root',
})
export class ConfigService {
  // Simple configuration service for ngrok/proxy setup
  // All API calls go through the same domain via proxy

  get baseUrl(): string {
    return environment.apiUrl || '/api';
  }

  get appBaseUrl(): string {
    return environment.baseUrl || '';
  }

  get authLoginUrl(): string {
    return '/api/auth/login';
  }

  get authRegisterUrl(): string {
    return '/api/auth/register';
  }

  get authProfileCompletionUrl(): string {
    return '/api/auth/profile-completion-status';
  }

  get profileUrl(): string {
    return '/api/profile';
  }

  get uploadPhotoUrl(): string {
    return '/api/image/upload-photo';
  }

  get generateImageUrl(): string {
    return '/api/image/generate-profile-picture';
  }

  get generateSamplesUrl(): string {
    return '/api/image/generate-samples';
  }

  get userImagesUrl(): string {
    return '/api/image/user-images';
  }

  get activeStylesUrl(): string {
    return '/api/style';
  }

  get generateBasicUrl(): string {
    return '/api/replicate/generate/basic';
  }

  get replicateCreditsUrl(): string {
    return '/api/test/basic-tier-status';
  }

  get imageStylesUrl(): string {
    return '/api/image/styles';
  }

  get imageListUrl(): string {
    return '/api/image/images';
  }

  get profileTrainingStatusUrl(): string {
    return '/api/profile/training-status';
  }

  /**
   * Get the OAuth base URL for external login
   */
  getOAuthBaseUrl(): string {
    // For ngrok configuration, use the backend API URL
    if (environment.apiUrl && environment.apiUrl.startsWith('https://')) {
      // Extract base URL from full API URL (remove /api suffix)
      return environment.apiUrl.replace('/api', '');
    }
    // Fallback to current origin for local development
    return window.location.origin;
  }

  /**
   * Get full URL for an endpoint
   */
  getFullUrl(endpoint: string): string {
    // Ensure endpoint starts with /
    if (!endpoint.startsWith('/')) {
      endpoint = '/' + endpoint;
    }

    // For API endpoints, prepend /api if not already present
    if (!endpoint.startsWith('/api/')) {
      endpoint = '/api' + endpoint;
    }

    return endpoint;
  }

  // Simplified properties for compatibility
  get frontendBaseUrl(): string {
    return window.location.origin;
  }

  get externalBaseUrl(): string {
    return window.location.origin;
  }

  getApiUrl(): string {
    return this.baseUrl;
  }

  isExternalAccess(): boolean {
    return !window.location.hostname.includes('localhost');
  }

  isNgrokAccess(): boolean {
    return (
      window.location.hostname.includes('ngrok.app') ||
      window.location.hostname.includes('ngrok.io')
    );
  }

  getCurrentEnvironment(): 'localhost' | 'ngrok' | 'test' | 'production' {
    const hostname = window.location.hostname;

    if (hostname.includes('localhost') || hostname.includes('127.0.0.1')) {
      return 'localhost';
    } else if (hostname.includes('ngrok.app') || hostname.includes('ngrok.io')) {
      return 'ngrok';
    } else if (hostname.includes('test.') || hostname.includes('-test.')) {
      return 'test';
    } else {
      return 'production';
    }
  }

  // Add getOAuthRedirectUrl for compatibility
  getOAuthRedirectUrl(): string {
    return this.getOAuthBaseUrl();
  }

  // Add apiConfig for compatibility with file-upload service
  get apiConfig() {
    return {
      endpoints: {
        image: {
          upload: '/image/upload',
          images: '/image/images',
          createTrainingZip: '/image/create-training-zip',
          trainingZips: '/image/training-zips',
          latestTrainingZip: '/image/latest-training-zip',
        },
      },
    };
  }

  /**
   * Build a complete API endpoint URL
   * @param endpoint - The endpoint path (with or without leading slash)
   * @returns Complete API URL
   */
  buildApiEndpoint(endpoint: string): string {
    const cleanEndpoint = endpoint.startsWith('/') ? endpoint.slice(1) : endpoint;
    return `${this.getApiUrl()}/${cleanEndpoint}`;
  }

  /**
   * Build a static file URL (for uploads, generated images, etc.)
   * @param path - The file path
   * @param baseEndpoint - The base endpoint (uploads, generated, style-previews)
   * @returns Complete static file URL
   */
  buildStaticFileUrl(path: string, baseEndpoint: string): string {
    const cleanPath = path.startsWith('/') ? path.slice(1) : path;
    const cleanBase = baseEndpoint.startsWith('/') ? baseEndpoint.slice(1) : baseEndpoint;
    return `${this.getApiUrl()}/${cleanBase}/${cleanPath}`;
  }

  /**
   * Build URL for uploaded user images
   * @param imagePath - The image path or filename
   * @param thumbnail - Whether to request thumbnail size (if supported)
   * @returns Complete upload URL
   */
  buildUploadUrl(imagePath: string, thumbnail = false): string {
    const url = this.buildStaticFileUrl(imagePath, 'uploads');
    // Future: Add thumbnail parameter when backend supports it
    // if (thumbnail) url += '?size=thumbnail';
    return url;
  }

  /**
   * Build URL for generated images
   * @param imagePath - The image path or filename
   * @returns Complete generated image URL
   */
  buildGeneratedImageUrl(imagePath: string): string {
    return this.buildStaticFileUrl(imagePath, 'generated');
  }

  /**
   * Build URL for style preview images
   * @param styleName - The style name
   * @returns Complete style preview URL
   */
  buildStylePreviewUrl(styleName: string): string {
    // Map style names to unique filenames that exist on the backend
    // Each style should have its own unique preview image
    const styleFileMap: Record<string, string> = {
      // Database style names (with hyphens - exact matches)
      academic: 'academic',
      artistic: 'artistic',
      author: 'author',
      casual: 'casual',
      consultant: 'consultant',
      corporate: 'corporate',
      creative: 'creative',
      'digital-nomad': 'digital-nomad',
      'edgy-urban': 'edgy-urban',
      entrepreneur: 'entrepreneur',
      executive: 'executive',
      fitness: 'fitness',
      glamour: 'glamour',
      influencer: 'influencer',
      legal: 'legal',
      linkedin: 'linkedin',
      medical: 'medical',
      spiritual: 'spiritual',
      startup: 'startup',
      'tech-professional': 'tech-professional',

      // Legacy fallback mappings (with spaces - for backwards compatibility)
      'professional linkedin': 'linkedin',
      'creative professional': 'creative',
      'corporate executive': 'corporate',
      'casual professional': 'casual',
      'classic headshot': 'corporate',
      'modern professional': 'linkedin',
      'elegant portrait': 'executive',
      'friendly professional': 'consultant',
      'confident leader': 'executive',
      'artistic expression': 'artistic',
      'business casual': 'casual',
      'tech professional': 'tech-professional',
      'senior executive': 'executive',
      'professional consultant': 'consultant',
      'academic professional': 'academic',
      'sales professional': 'consultant',
      'marketing expert': 'creative',
      'finance professional': 'corporate',
      'healthcare professional': 'medical',
      'digital nomad': 'digital-nomad',
      'edgy urban': 'edgy-urban',
    };

    const lowerStyleName = styleName.toLowerCase();
    const fileName = styleFileMap[lowerStyleName] || this.generateUniqueFileName(styleName);

    return `/style-previews/${fileName}.jpg`;
  }

  /**
   * Generate a unique filename for styles not in the map
   * @param styleName - The original style name
   * @returns A unique filename based on the style name
   */
  private generateUniqueFileName(styleName: string): string {
    return styleName
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, '') // Remove special characters
      .replace(/\s+/g, '-') // Replace spaces with hyphens
      .trim();
  }

  /**
   * Clean and normalize URL paths
   * @param url - URL to clean
   * @returns Cleaned URL
   */
  cleanUrl(url: string): string {
    return url.replace(/\/+/g, '/').replace(/\/$/, '');
  }

  /**
   * Check if image validation is enabled in the current environment
   * @returns true if image validation should be performed, false to skip
   */
  get isImageValidationEnabled(): boolean {
    return environment.features?.enableImageValidation ?? true;
  }

  /**
   * Check if Replicate credits API calls should be made
   * @returns true if Replicate API should be called, false to skip
   */
  get isReplicateCreditsEnabled(): boolean {
    return environment.features?.enableReplicateCredits ?? true;
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { ConfigService } from './config.service';

export interface CreditPackage {
  id: number;
  name: string;
  credits: number;
  bonusCredits: number;
  totalCredits: number;
  price: number;
  description: string;
  displayOrder: number;
}

export interface UserCreditStatus {
  totalCredits: number;
  weeklyCredits: number;
  purchasedCredits: number;
  lastCreditReset: string;
  nextResetDate: string;
}

export interface PurchaseCreditPackageRequest {
  packageId: number;
  paymentTransactionId?: string;
}

export interface CreditPurchase {
  id: number;
  purchaseDate: string;
  creditsAwarded: number;
  amountPaid: number;
  status: string;
  packageName: string;
}

export interface CreditCost {
  cost: number;
  canUseWeeklyCredits: boolean;
  description: string;
}

export interface CreditCosts {
  photoEnhancement: CreditCost;
  modelTraining: CreditCost;
  styledGeneration: CreditCost;
}

export interface PaymentConfig {
  paymentSimulation: {
    enabled: boolean;
    skipStripeIntegration: boolean;
  };
}

export interface ApiResponse<T> {
  success: boolean;
  data: T;
  error: {
    code: string;
    message: string;
  } | null;
}

@Injectable({
  providedIn: 'root',
})
export class CreditService {
  private _apiUrl: string;
  private _creditCosts: CreditCosts | null = null;

  constructor(
    private _http: HttpClient,
    private _configService: ConfigService
  ) {
    this._apiUrl = this._configService.getApiUrl();
  }

  /**
   * Get current user's credit status
   */
  getCreditStatus(): Observable<ApiResponse<UserCreditStatus>> {
    const endpoint = this._configService.buildApiEndpoint('credit/status');
    return this._http.get<ApiResponse<UserCreditStatus>>(endpoint);
  }

  /**
   * Get all available credit packages
   */
  getCreditPackages(): Observable<ApiResponse<CreditPackage[]>> {
    return this._http.get<ApiResponse<CreditPackage[]>>(
      this._configService.buildApiEndpoint('credit/packages')
    );
  }

  /**
   * Get payment configuration including simulation settings
   */
  getPaymentConfig(): Observable<ApiResponse<PaymentConfig>> {
    return this._http.get<ApiResponse<PaymentConfig>>(
      this._configService.buildApiEndpoint('credit/payment-config')
    );
  }

  /**
   * Create a payment intent for Stripe
   */
  createPaymentIntent(request: { packageId: number }): Observable<{ success: boolean; data: { clientSecret: string; isSimulation: boolean } }> {
    return this._http.post<{ success: boolean; data: { clientSecret: string; isSimulation: boolean } }>(
      this._configService.buildApiEndpoint('credit/create-payment-intent'),
      request
    );
  }

  /**
   * Purchase a credit package
   */
  purchaseCreditPackage(request: PurchaseCreditPackageRequest): Observable<ApiResponse<{ updatedCredits: UserCreditStatus }>> {
    return this._http.post<ApiResponse<{ updatedCredits: UserCreditStatus }>>(
      this._configService.buildApiEndpoint('credit/purchase'),
      request
    );
  }

  /**
   * Get user's credit purchase history
   */
  getPurchaseHistory(): Observable<ApiResponse<CreditPurchase[]>> {
    return this._http.get<ApiResponse<CreditPurchase[]>>(
      this._configService.buildApiEndpoint('credit/history')
    );
  }

  /**
   * Get credit costs configuration from API
   */
  getCreditCosts(): Observable<ApiResponse<CreditCosts>> {
    return this._http.get<ApiResponse<CreditCosts>>(
      this._configService.buildApiEndpoint('credit/costs')
    );
  }

  /**
   * Get credit cost for a specific operation (async version)
   */
  async getCreditCost(operation: string): Promise<number> {
    if (!this._creditCosts) {
      try {
        const response = await this.getCreditCosts().toPromise();
        if (response?.success) {
          this._creditCosts = response.data;
        }
      } catch (error) {
        console.error('Failed to fetch credit costs:', error);
        // Fallback to hardcoded values
        return this.getFallbackCreditCost(operation);
      }
    }

    switch (operation.toLowerCase()) {
      case 'photo_enhancement':
        return this._creditCosts?.photoEnhancement.cost || 1;
      case 'model_training':
        return this._creditCosts?.modelTraining.cost || 15;
      case 'styled_generation':
      case 'image_generation':
        return this._creditCosts?.styledGeneration.cost || 5;
      default:
        return 1;
    }
  }

  /**
   * Get credit cost for a specific operation (sync version with cached data)
   */
  getCreditCostSync(operation: string): number {
    if (!this._creditCosts) {
      return this.getFallbackCreditCost(operation);
    }

    switch (operation.toLowerCase()) {
      case 'photo_enhancement':
        return this._creditCosts.photoEnhancement.cost;
      case 'model_training':
        return this._creditCosts.modelTraining.cost;
      case 'styled_generation':
      case 'image_generation':
        return this._creditCosts.styledGeneration.cost;
      default:
        return 1;
    }
  }

  /**
   * Check if an operation can use weekly credits (async version)
   */
  async canUseWeeklyCredits(operation: string): Promise<boolean> {
    if (!this._creditCosts) {
      try {
        const response = await this.getCreditCosts().toPromise();
        if (response?.success) {
          this._creditCosts = response.data;
        }
      } catch (error) {
        console.error('Failed to fetch credit costs:', error);
        return this.getFallbackWeeklyCreditsUsage(operation);
      }
    }

    switch (operation.toLowerCase()) {
      case 'photo_enhancement':
        return this._creditCosts?.photoEnhancement.canUseWeeklyCredits || true;
      case 'model_training':
        return this._creditCosts?.modelTraining.canUseWeeklyCredits || false;
      case 'styled_generation':
      case 'image_generation':
        return this._creditCosts?.styledGeneration.canUseWeeklyCredits || false;
      default:
        return false;
    }
  }

  /**
   * Check if an operation can use weekly credits (sync version with cached data)
   */
  canUseWeeklyCreditSync(operation: string): boolean {
    if (!this._creditCosts) {
      return this.getFallbackWeeklyCreditsUsage(operation);
    }

    switch (operation.toLowerCase()) {
      case 'photo_enhancement':
        return this._creditCosts.photoEnhancement.canUseWeeklyCredits;
      case 'model_training':
        return this._creditCosts.modelTraining.canUseWeeklyCredits;
      case 'styled_generation':
      case 'image_generation':
        return this._creditCosts.styledGeneration.canUseWeeklyCredits;
      default:
        return false;
    }
  }

  /**
   * Load and cache credit costs
   */
  async loadCreditCosts(): Promise<void> {
    try {
      const response = await this.getCreditCosts().toPromise();
      if (response?.success) {
        this._creditCosts = response.data;
      }
    } catch (error) {
      console.error('Failed to load credit costs:', error);
    }
  }

  /**
   * Fallback credit costs (in case API fails)
   */
  private getFallbackCreditCost(operation: string): number {
    switch (operation.toLowerCase()) {
      case 'photo_enhancement':
        return 1;
      case 'model_training':
        return 15;
      case 'styled_generation':
      case 'image_generation':
        return 5;
      default:
        return 1;
    }
  }

  /**
   * Fallback weekly credits usage (in case API fails)
   */
  private getFallbackWeeklyCreditsUsage(operation: string): boolean {
    switch (operation.toLowerCase()) {
      case 'photo_enhancement':
        return true;
      case 'model_training':
      case 'styled_generation':
      case 'image_generation':
        return false;
      default:
        return false;
    }
  }

  /**
   * Calculate total available credits (weekly + purchased)
   */
  getTotalAvailableCredits(
    userCreditStatus: UserCreditStatus | null,
    creditsInfo: unknown
  ): number {
    const weeklyCredits = this.getWeeklyCredits(userCreditStatus, creditsInfo);
    const purchasedCredits = this.getPurchasedCredits(userCreditStatus);

    // Always calculate total from individual components to ensure accuracy
    return weeklyCredits + purchasedCredits;
  }

  /**
   * Get purchased credits from user credit status
   */
  getPurchasedCredits(userCreditStatus: UserCreditStatus | null): number {
    return userCreditStatus?.purchasedCredits || 0;
  }

  /**
   * Get weekly credits from user credit status with fallback to creditsInfo
   */
  getWeeklyCredits(userCreditStatus: UserCreditStatus | null, creditsInfo: unknown): number {
    // Use weeklyCredits from userCreditStatus first, fallback to creditsInfo.availableCredits
    return (
      userCreditStatus?.weeklyCredits ||
      (creditsInfo as { availableCredits?: number })?.availableCredits ||
      0
    );
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject, combineLatest, forkJoin, Observable, of } from 'rxjs';
import { catchError, map } from 'rxjs/operators';
import { ProfileService, UserProfile } from './profile.service';
import { ModelStateService } from './model-state.service';
import { FallbackOperationsService } from './fallback-operations.service';
import { CacheManagerService } from './cache-manager.service';
import { NotificationService } from './notification.service';
import { ImageStateService } from './image-state.service';
import { SubscriptionStateService } from './subscription-state.service';
import { FileUploadService } from './file-upload.service';
import { DashboardState, IDashboardStateService } from '../interfaces/service.interfaces';

/**
 * Orchestrates multiple specialized services to provide a unified dashboard interface
 * Replaces the monolithic DashboardStateService with a coordination-focused approach
 */
@Injectable({
  providedIn: 'root',
})
export class DashboardCoordinatorService implements IDashboardStateService {
  private readonly CACHE_KEY = 'dashboard_coordinator_data';

  // Core state for coordination
  private readonly _coordinatorState = new BehaviorSubject<{
    userProfile: UserProfile | null;
    modelStatus: string;
    latestTrainedModel: unknown;
    isLoading: boolean;
  }>({
    userProfile: null,
    modelStatus: 'Not Started',
    latestTrainedModel: null,
    isLoading: false,
  });

  // Combined dashboard state observable
  public readonly state$: Observable<DashboardState>;

  constructor(
    private _profileService: ProfileService,
    private _modelState: ModelStateService,
    private _fallbackOps: FallbackOperationsService,
    private _cacheManager: CacheManagerService,
    private _notificationService: NotificationService,
    private _imageState: ImageStateService,
    private _subscriptionState: SubscriptionStateService,
    private _fileUploadService: FileUploadService
  ) {
    // Combine states from specialized services
    this.state$ = combineLatest([
      this._coordinatorState.asObservable(),
      this._imageState.state$,
      this._subscriptionState.state$,
    ]).pipe(
      map(([coordinator, images, subscription]) => ({
        // Profile and model data
        userProfile: coordinator.userProfile,
        modelStatus: coordinator.modelStatus,
        latestTrainedModel: coordinator.latestTrainedModel,

        // Image data from ImageStateService
        uploadedImages: images.uploadedImages,
        uploadedImageThumbnails: images.uploadedImageThumbnails,
        generatedPhotosCount: images.generatedPhotosCount,
        imagesValidated: images.imagesValidated,
        lastValidationTime: images.lastValidationTime,

        // Subscription data from SubscriptionStateService
        userCreditStatus: subscription.userCreditStatus,
        creditsInfo: subscription.creditsInfo,
        totalCredits: subscription.totalCredits,
        isPremiumWorkflow: subscription.isPremiumWorkflow,

        // Loading state (true if any service is loading)
        isLoading: coordinator.isLoading || images.isLoading || subscription.isLoading,
      }))
    );
  }

  /**
   * Get current combined dashboard state
   */
  getState(): DashboardState {
    const coordinator = this._coordinatorState.getValue();
    const images = this._imageState.getState();
    const subscription = this._subscriptionState.getState();

    return {
      userProfile: coordinator.userProfile,
      modelStatus: coordinator.modelStatus,
      latestTrainedModel: coordinator.latestTrainedModel,
      uploadedImages: images.uploadedImages,
      uploadedImageThumbnails: images.uploadedImageThumbnails,
      generatedPhotosCount: images.generatedPhotosCount,
      imagesValidated: images.imagesValidated,
      lastValidationTime: images.lastValidationTime,
      userCreditStatus: subscription.userCreditStatus,
      creditsInfo: subscription.creditsInfo,
      totalCredits: subscription.totalCredits,
      isPremiumWorkflow: subscription.isPremiumWorkflow,
      isLoading: coordinator.isLoading || images.isLoading || subscription.isLoading,
    };
  }

  /**
   * Update partial state (delegates to appropriate service)
   */
  setState(newState: Partial<DashboardState>): void {
    // Update coordinator state if relevant fields are present
    const coordinatorFields = ['userProfile', 'modelStatus', 'latestTrainedModel', 'isLoading'];
    const hasCoordinatorFields = coordinatorFields.some(field => field in newState);

    if (hasCoordinatorFields) {
      const currentCoordinator = this._coordinatorState.getValue();
      this._coordinatorState.next({
        ...currentCoordinator,
        ...(newState.userProfile !== undefined && { userProfile: newState.userProfile }),
        ...(newState.modelStatus !== undefined && { modelStatus: newState.modelStatus }),
        ...(newState.latestTrainedModel !== undefined && {
          latestTrainedModel: newState.latestTrainedModel,
        }),
        ...(newState.isLoading !== undefined && { isLoading: newState.isLoading }),
      });
    }

    // Delegate image-related updates to ImageStateService
    const imageFields = [
      'uploadedImages',
      'uploadedImageThumbnails',
      'generatedPhotosCount',
      'imagesValidated',
      'lastValidationTime',
    ];
    const imageUpdate = imageFields.reduce((acc, field) => {
      if (field in newState) {
        acc[field] = newState[field as keyof DashboardState];
      }
      return acc;
    }, {} as Record<string, unknown>);

    if (Object.keys(imageUpdate).length > 0) {
      this._imageState.setState(imageUpdate);
    }

    // Delegate subscription-related updates to SubscriptionStateService
    const subscriptionFields = [
      'userCreditStatus',
      'creditsInfo',
      'totalCredits',
      'isPremiumWorkflow',
    ];
    const subscriptionUpdate = subscriptionFields.reduce((acc, field) => {
      if (field in newState) {
        acc[field] = newState[field as keyof DashboardState];
      }
      return acc;
    }, {} as Record<string, unknown>);

    if (Object.keys(subscriptionUpdate).length > 0) {
      this._subscriptionState.setState(subscriptionUpdate);
    }
  }

  /**
   * Load complete dashboard data by orchestrating specialized services
   */
  async loadInitialDashboardData(): Promise<void> {
    const startTime = performance.now();

    // Check if we should debounce this load
    if (
      this._cacheManager.shouldDebounceRequest(
        'dashboard_coordinator_load',
        CacheManagerService.LOAD_DEBOUNCE_MS
      )
    ) {
      return;
    }

    this.setCoordinatorLoading(true);

    try {
      // Load profile data (coordinator responsibility)
      const profilePromise = this.loadProfileData();

      // Load specialized service data in parallel
      const imagePromise = this._imageState.loadUserImages();
      const subscriptionPromise = this._subscriptionState.loadFullSubscriptionData();

      // Wait for core data to load
      await Promise.all([profilePromise, imagePromise, subscriptionPromise]);

      // Load remaining data asynchronously (non-blocking)
      this.loadRemainingDataAsync();

      const loadTime = performance.now() - startTime;
    } catch (error) {
      console.error('❌ Dashboard coordination failed:', error);
      this._notificationService.error(
        'Dashboard Load Failed',
        'Could not load dashboard data. Please try again.'
      );
    } finally {
      this.setCoordinatorLoading(false);
    }
  }

  /**
   * Load basic data for settings page (counts only, no validation)
   */
  async loadBasicDataForSettings(): Promise<void> {
    try {
      // Load profile data
      await this.loadProfileData();

      // Load only internal credits (faster)
      await this._subscriptionState.loadCreditsOnly();

      // Load user images without validation
      await this._imageState.loadUserImages();
    } catch (error) {
      console.error('❌ Settings data load failed:', error);
    }
  }

  /**
   * Load only internal credits
   */
  async loadCreditsOnly(): Promise<void> {
    await this._subscriptionState.loadCreditsOnly();
  }

  /**
   * Load profile data (coordinator responsibility)
   */
  private async loadProfileData(): Promise<void> {
    try {
      const profile = await this._profileService
        .getCurrentUserProfile()
        .pipe(
          catchError(error => {
            console.warn('⚠️ Profile API failed:', error);
            return of({ success: false, data: null, error });
          })
        )
        .toPromise();

      const userProfile = profile?.success ? profile.data : null;

      const currentState = this._coordinatorState.getValue();
      this._coordinatorState.next({
        ...currentState,
        userProfile,
      });
    } catch (error) {
      console.error('Failed to load profile data:', error);
    }
  }

  /**
   * Load remaining data asynchronously after initial render
   */
  private loadRemainingDataAsync(): void {
    forkJoin({
      trainingStatus: this._fileUploadService.getTrainingStatus().pipe(
        catchError(error => {
          console.warn('⚠️ Training Status API failed:', error);
          return of(null);
        })
      ),
      modelRequests: this._fileUploadService.getUserModelRequests().pipe(
        catchError(error => {
          console.warn('⚠️ Model Requests API failed:', error);
          return of({ success: false, data: null, error });
        })
      ),
    }).subscribe({
      next: ({ trainingStatus, modelRequests }) => {
        const modelRequestsData = modelRequests?.success ? modelRequests.data : null;
        const trainingStatusData = trainingStatus;

        // Get model status using ModelStateService
        const modelInfo = this._modelState.getModelStatusFromData(
          modelRequestsData,
          trainingStatusData
        );

        const currentState = this._coordinatorState.getValue();
        this._coordinatorState.next({
          ...currentState,
          modelStatus: modelInfo.modelStatus,
          latestTrainedModel: modelInfo.latestTrainedModel,
        });

        // Reset fallback tracking periodically
        this._fallbackOps.resetFallbackTracking();

        // Check if fallback operations are needed
        const dashboardState = this.getState();
        const fallbackCheck = this._fallbackOps.checkIfFallbackNeeded({
          generatedPhotosCount: dashboardState.generatedPhotosCount,
          modelStatus: modelInfo.modelStatus,
          hasLatestTrainedModel: !!modelInfo.latestTrainedModel,
          uploadedImages: dashboardState.uploadedImages,
          hasUserProfile: !!dashboardState.userProfile,
          latestTrainedModel: modelInfo.latestTrainedModel,
        });

        // Execute fallback operations if needed
        if (fallbackCheck.shouldCheckFilesystem) {
          this._fallbackOps.checkGeneratedImagesFromFilesystem().subscribe({
            next: result => {
              if (result.actualGeneratedCount) {
                this._imageState.setState({ generatedPhotosCount: result.actualGeneratedCount });
              }
            },
            error: error => console.error('Filesystem check failed:', error),
          });
        }

        if (fallbackCheck.shouldDiscoverModels) {
          this._modelState.runAsyncModelDiscovery();
        }
      },
      error: error => {
        console.error('Failed to load additional dashboard data:', error);
        const currentState = this._coordinatorState.getValue();
        if (currentState.modelStatus === 'Loading...') {
          this._coordinatorState.next({
            ...currentState,
            modelStatus: 'Not Started',
          });
        }
      },
    });
  }

  /**
   * Set coordinator loading state
   */
  private setCoordinatorLoading(isLoading: boolean): void {
    const currentState = this._coordinatorState.getValue();
    this._coordinatorState.next({
      ...currentState,
      isLoading,
    });
  }

  /**
   * Reset state for all services
   */
  resetState(): void {
    this._coordinatorState.next({
      userProfile: null,
      modelStatus: 'Not Started',
      latestTrainedModel: null,
      isLoading: false,
    });

    this._imageState.resetState();
    this._subscriptionState.resetState();
    this._cacheManager.invalidateCache(this.CACHE_KEY);
  }

  /**
   * Force refresh all services
   */
  forceRefresh(): void {
    this._cacheManager.forceRefresh(this.CACHE_KEY);
    this._fallbackOps.resetFallbackTracking();

    // Force refresh specialized services
    this._imageState.forceRefresh();
    this._subscriptionState.forceRefresh();

    // Reload dashboard data
    this.loadInitialDashboardData();
  }

  /**
   * Invalidate and refresh images (delegate to ImageStateService)
   */
  invalidateAndRefreshImages(): void {
    this._imageState.invalidateAndRefresh();
  }

  /**
   * Refresh generated photos count (delegate to ImageStateService)
   */
  refreshGeneratedPhotosCount(): void {
    this._imageState.refreshGeneratedPhotosCount();
  }
}

