        // Process uploaded images into thumbnails format
        const userImagesData = userImages?.success ? userImages.data : null;

        // Process and validate uploaded images with robust filtering
        const rawImageThumbnails: UploadedImageThumbnail[] =
          userImagesData?.images
            ?.filter((img: any) => {
              // Early exit: Skip generated images entirely (no logging, no processing)
              if (img.isGenerated) {
                return false;
              }

              // Only process uploaded images from here
              const isOriginalByFlag = img.isOriginalUpload;
              // Secondary check: Use style as fallback for corrupted flags
              const isOriginalByStyle = img.style === 'Original';
              // Must have a valid URL
              const hasUrl = !!img.originalImageUrl;

              // Robust filtering: Image is considered uploaded selfie if:
              // 1. Has IsOriginalUpload flag true, OR
              // 2. Has "Original" style (even if flag is corrupted), AND
              // 3. Has a valid URL, AND
              // 4. Is NOT an enhanced image
              const isUploadedImage = (isOriginalByFlag || isOriginalByStyle) && hasUrl;

              // Only log uploaded images (much cleaner console)

              // Skip logging flag/style mismatch - handled by image validation service

              return isUploadedImage;
            })
            ?.map((img: any) => ({
              id: img.id,
              url: img.originalImageUrl,
              fileName: `Image ${img.id}`, // Use a default filename since it's not in ProcessedImage
            })) || [];

        // Clean URLs immediately to prevent browser caching issues
        const uploadedImageThumbnails = rawImageThumbnails.map(thumb => ({
          ...thumb,
          url: this.cleanImageUrl(thumb.url),
        }));

        // Validate images asynchronously after state is set with clean URLs
        if (uploadedImageThumbnails.length > 0) {
          this.validateAndCleanupImages(uploadedImageThumbnails, false).then(result => {
            if (result.removedCount > 0) {
              this.updateStateWithValidatedImages(
                result.validImages,
                result.removedCount,
                result.repairTriggered
              );
            }
          });
        }

        // Count generated photos (use API count or filter generated images)
        const generatedPhotosCount =
          userImagesData?.generatedImages ||
          userImagesData?.images?.filter((img: any) => img.isGenerated)?.length ||
          0;

        // Check if we need immediate filesystem repair
        if (generatedPhotosCount === 0 && uploadedImageThumbnails.length > 0) {
        }

        // 🔧 FIX: Use total credits from subscription service
        const totalCredits = subscriptionData.totalCredits;

        // Set initial state with critical data for fast render
        const newState = {
          userProfile,
          userCreditStatus,
          creditsInfo,
          uploadedImages: uploadedImageThumbnails.length,
          uploadedImageThumbnails,
          generatedPhotosCount,
          modelStatus: 'Loading...', // Temporary status
          isPremiumWorkflow: subscriptionData.isPremiumWorkflow,
          isLoading: false,
          totalCredits,
        };

        this.setState(newState);

        // Cache the loaded data
        this.cacheManager.setCachedData(
          'dashboard_data',
          this.getState(),
          CacheManagerService.DASHBOARD_CACHE_DURATION_MS
        );
        const loadTime = performance.now() - loadStartTime;

        // Load remaining data asynchronously (non-blocking)
        this.loadRemainingDataAsync();

        // Set a timeout to avoid infinite "Loading..." state
        setTimeout(() => {
          const currentState = this.getState();
          if (currentState.modelStatus === 'Loading...') {
            this.setState({ modelStatus: 'Not Started' });
          }
        }, 10000);
      },
      error: error => {
        // Log only critical errors (500+ status codes)
        if (error?.status >= 500 || !error?.status) {
          console.error('❌ Dashboard API call failed:', error);
        }
        this.notificationService.error(
          'Dashboard Load Failed',
          'Could not load dashboard data. Please try again.'
        );
        this.setState({
          isLoading: false,
          modelStatus: 'Error',
        });
      },
    });
  }

  resetState() {
    this._state.next(this.initialState);
    this.cacheManager.invalidateCache('dashboard_data');
  }

  // Force refresh by clearing cache and reloading
  forceRefresh() {
    this.cacheManager.forceRefresh('dashboard_data');
    this.fallbackOps.resetFallbackTracking();
    this.fileUploadService.invalidateUserImagesCache();
    this.imageValidation.clearCache(); // Clear image validation cache too

    // Reset validation state to force re-validation
    this.setState({
      imagesValidated: false,
      lastValidationTime: 0,
    });

    this.loadInitialDashboardData();
  }

  // Force refresh after repair to sync counts with server reality
  private async forceRefreshAfterRepair(): Promise<void> {
    try {
      // Clear all caches to ensure fresh data
      this.cacheManager.forceRefresh('dashboard_data');
      this.fileUploadService.invalidateUserImagesCache();
      this.imageValidation.clearCache();

      // Get fresh data from server
      const userImages = await this.fileUploadService.getUserImages(true).toPromise();

      if (userImages?.success && userImages.data) {
        const userImagesData = userImages.data;

        // Process images with robust validation (same logic as initial load)
        const uploadedImageThumbnails: UploadedImageThumbnail[] =
          userImagesData.images
            ?.filter(img => {
              const isOriginalByFlag = img.isOriginalUpload;
              const isOriginalByStyle = img.style === 'Original';
              const isNotGenerated = !img.isGenerated;
              const hasUrl = !!img.originalImageUrl;
              return (isOriginalByFlag || isOriginalByStyle) && isNotGenerated && hasUrl;
            })
            ?.map(img => ({
              id: img.id,
              url: img.originalImageUrl,
              fileName: `Image ${img.id}`,
            })) || [];

        // Update state with accurate counts - force validation of fresh data
        this.setState({
          uploadedImageThumbnails,
          uploadedImages: uploadedImageThumbnails.length,
          imagesValidated: false, // Force validation to run on fresh data
          lastValidationTime: 0,
        });
      }
    } catch (error) {
      // Silent failure - repair issues are handled by parent caller
    }
  }

  // Sync user images cache with current state
  invalidateAndRefreshImages() {
    this.fileUploadService.invalidateUserImagesCache();
    this.refreshGeneratedPhotosCount();
  }

  // Load remaining data asynchronously after initial render
  private loadRemainingDataAsync() {
    // Load non-critical data in parallel but don't block rendering
    forkJoin({
      trainingStatus: this.fileUploadService.getTrainingStatus().pipe(
        catchError(error => {
          return of(null); // Return null for failed training status
        })
      ),
      modelRequests: this.fileUploadService.getUserModelRequests().pipe(
        catchError(error => {
          return of({ success: false, data: null, error });
        })
      ),
    }).subscribe({
      next: ({ trainingStatus, modelRequests }) => {
        const currentState = this.getState();
        const modelRequestsData = modelRequests?.success ? modelRequests.data : null;

        // Training status is either TrainingStatusResponse or null
        const trainingStatusData = trainingStatus; // Use directly since it's not wrapped

        // Get model status using ModelStateService
        const modelInfo = this.modelState.getModelStatusFromData(
          modelRequestsData,
          trainingStatusData
        );
        const { modelStatus, hasTrainedModel, latestTrainedModel } = modelInfo;

        // Update state with additional data
        this.setState({
          uploadedImages: trainingStatusData?.totalUploadedImages || currentState.uploadedImages,
          modelStatus,
          latestTrainedModel,
        });

        // Reset fallback tracking periodically
        this.fallbackOps.resetFallbackTracking();

        // Check if fallback operations are needed
        const fallbackCheck = this.fallbackOps.checkIfFallbackNeeded({
          generatedPhotosCount: currentState.generatedPhotosCount,
          modelStatus,
          hasLatestTrainedModel: !!latestTrainedModel,
          uploadedImages: currentState.uploadedImages,
          hasUserProfile: !!currentState.userProfile,
          latestTrainedModel,
        });

        // Execute fallback operations if needed
        if (fallbackCheck.shouldCheckFilesystem) {
          this.fallbackOps.checkGeneratedImagesFromFilesystem().subscribe({
            next: result => {
              if (result.actualGeneratedCount) {
                this.setState({ generatedPhotosCount: result.actualGeneratedCount });
              }
            },
            error: error => {}, // Silent failure for filesystem check
          });
        }

        if (fallbackCheck.shouldDiscoverModels) {
          this.modelState.runAsyncModelDiscovery();
        }
      },
      error: error => {
        // Set fallback model status on async load failure
        const currentState = this.getState();
        if (currentState.modelStatus === 'Loading...') {
          this.setState({ modelStatus: 'Not Started' });
        }
        // Don't show error to user since initial data loaded successfully
      },
    });
  }

  // Removed sync workarounds - ModelCreationRequest is now the single source of truth

  // Refresh only the photos count after generation completion
  refreshGeneratedPhotosCount() {
    this.fileUploadService
      .getUserImages()
      .pipe(
        catchError(error => {
          return of({ success: false, data: null, error });
        })
      )
      .subscribe({
        next: userImages => {
          const userImagesData = userImages?.success ? userImages.data : null;
          const generatedPhotosCount =
            userImagesData?.generatedImages ||
            userImagesData?.images?.filter(img => img.isGenerated)?.length ||
            0;

          this.setState({ generatedPhotosCount });
        },
        error: error => {
          // Silent failure for photo count refresh
        },
      });
  }

  // Validate cached images and update state if needed
  private async validateCachedImages(images: UploadedImageThumbnail[]): Promise<void> {
    // Check if validation is recent enough (5 minutes)
    const currentState = this.getState();
    const validationAge = Date.now() - (currentState.lastValidationTime || 0);
    const VALIDATION_TTL = 5 * 60 * 1000; // 5 minutes

    if (currentState.imagesValidated && validationAge < VALIDATION_TTL) {
      return;
    }

    const result = await this.validateAndCleanupImages(images, true);

    if (result.removedCount > 0) {
      this.updateStateWithValidatedImages(
        result.validImages,
        result.removedCount,
        result.repairTriggered
      );
    } else {
      // Mark as validated even if no cleanup needed
      this.setState({
        imagesValidated: true,
        lastValidationTime: Date.now(),
      });
    }
  }

  // Validate and cleanup broken images
  private async validateAndCleanupImages(
    images: UploadedImageThumbnail[],
    isFromCache: boolean
  ): Promise<{
    validImages: UploadedImageThumbnail[];
    removedCount: number;
    repairTriggered?: boolean;
  }> {
    // Check if image validation is disabled via environment configuration
    if (!this.configService.isImageValidationEnabled) {
      return {
        validImages: images, // Return all images as valid
        removedCount: 0,
        repairTriggered: false,
      };
    }

    const validation = await this.imageValidation.filterValidImages(images);

    if (validation.removedCount > 0) {
      // Trigger repair if 404s were found (orphaned database records)
      if (validation.repairSuggested && validation.notFoundCount > 0) {
        try {
          const repairResult = await this.fileUploadService.repairImageDatabase().toPromise();
          if (repairResult?.success) {
            // Force refresh from server to get accurate counts after repair
            await this.forceRefreshAfterRepair();

            return {
              validImages: validation.validImages,
              removedCount: validation.removedCount,
              repairTriggered: true,
            };
          }
        } catch (repairError) {
          // Silent failure - repair error is handled by caller
        }
      }
    }

    return {
      validImages: validation.validImages,
      removedCount: validation.removedCount,
      repairTriggered: false,
    };
  }

  // Update state with validated images and invalidate cache if needed
  private updateStateWithValidatedImages(
    validImages: UploadedImageThumbnail[],
    removedCount: number,
    repairTriggered?: boolean
  ): void {
    this.setState({
      uploadedImageThumbnails: validImages,
      uploadedImages: validImages.length,
      imagesValidated: true,
      lastValidationTime: Date.now(),
    });

    // Invalidate cache since we have new data
    this.cacheManager.invalidateCache('dashboard_data');

    // Show notification if images were removed
    if (removedCount > 0) {
      const message = repairTriggered
        ? `Removed ${removedCount} broken image reference(s) and repaired database inconsistencies.`
        : `Removed ${removedCount} broken image reference(s) that could no longer be loaded.`;

      this.notificationService.info(
        repairTriggered ? 'Cleaned up & Repaired' : 'Cleaned up broken images',
        message
      );
    }
  }

  // Clean image URL to remove fragments and cache-busting artifacts
  private cleanImageUrl(url: string): string {
    try {
      // Remove URL fragments (#) and normalize
      const cleanUrl = url.split('#')[0].split('?')[0];

      // Ensure proper leading slash for relative URLs
      if (!cleanUrl.startsWith('http') && !cleanUrl.startsWith('/')) {
        return '/' + cleanUrl;
      }

      return cleanUrl;
    } catch (error) {
      return url;
    }
  }

  // Public method for manual validation (debug purposes)
  async validateCurrentImages(): Promise<void> {
    const currentState = this.getState();
    const images = currentState.uploadedImageThumbnails;

    if (images.length === 0) {
      return;
    }

    const result = await this.validateAndCleanupImages(images, false);

    if (result.removedCount > 0) {
      this.updateStateWithValidatedImages(
        result.validImages,
        result.removedCount,
        result.repairTriggered
      );

      const message = result.repairTriggered
        ? `Validated ${images.length} images. Removed ${result.removedCount} broken references and repaired database.`
        : `Validated ${images.length} images. Removed ${result.removedCount} broken references.`;

      this.notificationService.info(
        result.repairTriggered ? 'Validation & Repair Complete' : 'Image Validation Complete',
        message
      );
    } else {
      // Mark as validated
      this.setState({
        imagesValidated: true,
        lastValidationTime: Date.now(),
      });

      this.notificationService.success(
        'All Images Valid',
        'All uploaded images are accessible and valid.'
      );
    }
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject, catchError, combineLatest, map, Observable, of, tap } from 'rxjs';
import { ProfileService, UserProfile } from './profile.service';
import { FileUploadService, ProcessedImage } from './file-upload.service';
import { CreditsInfo, ReplicateService } from './replicate.service';
import { Style, StyleService } from './style.service';

export interface DashboardState {
  userProfile: UserProfile | null;
  uploadedImages: ProcessedImage[];
  availableStyles: Style[];
  selectedStyles: Style[];
  generatedPhotos: ProcessedImage[];
  creditsInfo: CreditsInfo | null;
  trainingStatus: any;
  currentStep: number;
  loading: {
    profile: boolean;
    images: boolean;
    styles: boolean;
    credits: boolean;
    upload: boolean;
    generation: boolean;
  };
  errors: {
    profile: string | null;
    images: string | null;
    styles: string | null;
    credits: string | null;
    upload: string | null;
    generation: string | null;
  };
}

@Injectable({
  providedIn: 'root'
})
export class DashboardService {
  private stateSubject = new BehaviorSubject<DashboardState>(this.getInitialState());
  public state$ = this.stateSubject.asObservable();

  constructor(
    private profileService: ProfileService,
    private fileUploadService: FileUploadService,
    private replicateService: ReplicateService,
    private styleService: StyleService
  ) {}

  private getInitialState(): DashboardState {
    return {
      userProfile: null,
      uploadedImages: [],
      availableStyles: [],
      selectedStyles: [],
      generatedPhotos: [],
      creditsInfo: null,
      trainingStatus: null,
      currentStep: 1,
      loading: {
        profile: false,
        images: false,
        styles: false,
        credits: false,
        upload: false,
        generation: false
      },
      errors: {
        profile: null,
        images: null,
        styles: null,
        credits: null,
        upload: null,
        generation: null
      }
    };
  }

  // Initialize dashboard data
  initializeDashboard(): Observable<DashboardState> {
    this.updateLoadingState({ profile: true, images: true, styles: true, credits: true });

    return combineLatest([
      this.loadUserProfile(),
      this.loadUserImages(),
      this.loadAvailableStyles(),
      this.loadCreditsInfo()
    ]).pipe(
      map(() => this.stateSubject.value),
      tap(() => this.updateCurrentStep()),
      tap(() => this.updateLoadingState({ profile: false, images: false, styles: false, credits: false }))
    );
  }

  // Profile Management
  loadUserProfile(): Observable<UserProfile | null> {
    this.updateLoadingState({ profile: true });
    this.clearError('profile');

    return this.profileService.getCurrentUserProfile().pipe(
      tap(response => {
        if (response.success) {
          this.updateState({ userProfile: response.data });
        } else {
          this.updateError('profile', 'Failed to load user profile');
        }
        this.updateLoadingState({ profile: false });
      }),
      map(response => response.success ? response.data : null),
      catchError(error => {
        this.updateError('profile', error.message || 'Failed to load user profile');
        this.updateLoadingState({ profile: false });
        return of(null);
      })
    );
  }

  updateUserProfile(profile: any): Observable<UserProfile | null> {
    this.updateLoadingState({ profile: true });
    this.clearError('profile');

    return this.profileService.updateProfile(profile).pipe(
      tap(response => {
        if (response.success) {
          this.updateState({ userProfile: response.data });
        } else {
          this.updateError('profile', 'Failed to update profile');
        }
        this.updateLoadingState({ profile: false });
      }),
      map(response => response.success ? response.data : null),
      catchError(error => {
        this.updateError('profile', error.message || 'Failed to update profile');
        this.updateLoadingState({ profile: false });
        return of(null);
      })
    );
  }

  // File Upload Management
  loadUserImages(): Observable<ProcessedImage[]> {
    this.updateLoadingState({ images: true });
    this.clearError('images');

    return this.fileUploadService.getUserImages().pipe(
      tap(response => {
        if (response.success) {
          this.updateState({ uploadedImages: response.data });
        } else {
          this.updateError('images', 'Failed to load images');
        }
        this.updateLoadingState({ images: false });
      }),
      map(response => response.success ? response.data : []),
      catchError(error => {
        this.updateError('images', error.message || 'Failed to load images');
        this.updateLoadingState({ images: false });
        return of([]);
      })
    );
  }

  uploadImages(files: File[]): Observable<{ progress: number; completed: boolean; success: boolean }> {
    this.updateLoadingState({ upload: true });
    this.clearError('upload');

    return this.fileUploadService.uploadImages(files).pipe(
      map(result => {
        if (result.response) {
          // Upload completed
          this.updateLoadingState({ upload: false });
          if (result.response.success) {
            this.loadUserImages(); // Refresh images
            this.updateCurrentStep();
            return { progress: 100, completed: true, success: true };
          } else {
            this.updateError('upload', result.response.message || 'Upload failed');
            return { progress: 100, completed: true, success: false };
          }
        } else {
          // Upload in progress
          return { progress: result.progress, completed: false, success: true };
        }
      }),
      catchError(error => {
        this.updateError('upload', error.message || 'Upload failed');
        this.updateLoadingState({ upload: false });
        return of({ progress: 0, completed: true, success: false });
      })
    );
  }

  // Style Management
  loadAvailableStyles(): Observable<Style[]> {
    this.updateLoadingState({ styles: true });
    this.clearError('styles');

    return this.styleService.getActiveStyles().pipe(
      tap(response => {
        if (response.success) {
          this.updateState({ availableStyles: response.data });
        } else {
          this.updateError('styles', 'Failed to load styles');
        }
        this.updateLoadingState({ styles: false });
      }),
      map(response => response.success ? response.data : []),
      catchError(error => {
        this.updateError('styles', error.message || 'Failed to load styles');
        this.updateLoadingState({ styles: false });
        return of([]);
      })
    );
  }

  selectStyles(styleIds: number[]): Observable<boolean> {
    this.clearError('styles');

    return this.styleService.selectStyles({ styleIds }).pipe(
      tap(response => {
        if (response.success) {
          const selectedStyles = this.stateSubject.value.availableStyles.filter(s => styleIds.includes(s.id));
          this.updateState({ selectedStyles });
          this.updateCurrentStep();
        } else {
          this.updateError('styles', response.message || 'Failed to select styles');
        }
      }),
      map(response => response.success),
      catchError(error => {
        this.updateError('styles', error.message || 'Failed to select styles');
        return of(false);
      })
    );
  }

  // Credits Management
  loadCreditsInfo(): Observable<CreditsInfo | null> {
    this.updateLoadingState({ credits: true });
    this.clearError('credits');

    return this.replicateService.getCredits().pipe(
      tap(response => {
        if (response.success) {
          this.updateState({ creditsInfo: response.data });
        } else {
          this.updateError('credits', 'Failed to load credits info');
        }
        this.updateLoadingState({ credits: false });
      }),
      map(response => response.success ? response.data : null),
      catchError(error => {
        this.updateError('credits', error.message || 'Failed to load credits info');
        this.updateLoadingState({ credits: false });
        return of(null);
      })
    );
  }

  // Free Generation
  generateBasicImage(gender: string, userInfo?: any): Observable<{ success: boolean; creditsRemaining?: number }> {
    this.updateLoadingState({ generation: true });
    this.clearError('generation');

    return this.replicateService.generateBasicImage({ gender, userInfo }).pipe(
      tap(response => {
        if (response.success) {
          // Update credits info
          this.loadCreditsInfo();
          // Refresh images to include new generation
          this.loadUserImages();
        } else {
          this.updateError('generation', response.error?.message || 'Failed to generate image');
        }
        this.updateLoadingState({ generation: false });
      }),
      map(response => ({
        success: response.success,
        creditsRemaining: response.data?.creditsRemaining
      })),
      catchError(error => {
        this.updateError('generation', error.error?.message || 'Failed to generate image');
        this.updateLoadingState({ generation: false });
        return of({ success: false });
      })
    );
  }

  // Current step calculation
  private updateCurrentStep(): void {
    const state = this.stateSubject.value;
    let currentStep = 1;

    if (state.uploadedImages.length > 0) {
      currentStep = 2;

      if (state.trainingStatus === 'trained') {
        currentStep = 3;

        if (state.selectedStyles.length > 0) {
          currentStep = 4;
        }
      }
    }

    this.updateState({ currentStep });
  }

  // State management helpers
  private updateState(updates: Partial<DashboardState>): void {
    const currentState = this.stateSubject.value;
    this.stateSubject.next({ ...currentState, ...updates });
  }

  private updateLoadingState(loadingUpdates: Partial<DashboardState['loading']>): void {
    const currentState = this.stateSubject.value;
    this.updateState({ 
      loading: { ...currentState.loading, ...loadingUpdates } 
    });
  }

  private updateError(errorKey: keyof DashboardState['errors'], message: string): void {
    const currentState = this.stateSubject.value;
    this.updateState({ 
      errors: { ...currentState.errors, [errorKey]: message } 
    });
  }

  private clearError(errorKey: keyof DashboardState['errors']): void {
    const currentState = this.stateSubject.value;
    this.updateState({ 
      errors: { ...currentState.errors, [errorKey]: null } 
    });
  }

  // Getters for specific state slices
  get userProfile$(): Observable<UserProfile | null> {
    return this.state$.pipe(map(state => state.userProfile));
  }

  get uploadedImages$(): Observable<ProcessedImage[]> {
    return this.state$.pipe(map(state => state.uploadedImages));
  }

  get availableStyles$(): Observable<Style[]> {
    return this.state$.pipe(map(state => state.availableStyles));
  }

  get creditsInfo$(): Observable<CreditsInfo | null> {
    return this.state$.pipe(map(state => state.creditsInfo));
  }

  get currentStep$(): Observable<number> {
    return this.state$.pipe(map(state => state.currentStep));
  }

  get loading$(): Observable<DashboardState['loading']> {
    return this.state$.pipe(map(state => state.loading));
  }

  get errors$(): Observable<DashboardState['errors']> {
    return this.state$.pipe(map(state => state.errors));
  }
}

import { Injectable, NgZone } from '@angular/core';
import * as faceapi from 'face-api.js';
import { ModelLoaderService } from './model-loader.service';
import { ImageQualityService } from './image-quality.service';
import { FaceValidationResult, IFaceDetectionService, QualityScore } from '../interfaces/service.interfaces';

@Injectable({
  providedIn: 'root'
})
export class FaceDetectionService implements IFaceDetectionService {

  constructor(
    private ngZone: NgZone,
    private modelLoader: ModelLoaderService,
    private imageQuality: ImageQualityService
  ) {}


  /**
   * Validate image for face count, body type, and quality
   */
  async validateImage(file: File): Promise<FaceValidationResult> {
    try {
      await this.modelLoader.loadModels();

      const img = await this.imageQuality.loadImageElement(file);
      const detections = await this.ngZone.runOutsideAngular(async () => {
        return faceapi
          .detectAllFaces(img, new faceapi.TinyFaceDetectorOptions())
          .withFaceLandmarks(true);
      });

      const faceCount = detections.length;
      const errors: string[] = [];
      const warnings: string[] = [];

      // Check for close-up/cropped photos first
      const isCloseUpPhoto = this.detectCloseUpPhoto(img, detections);

      // Face count validation with improved messaging
      if (faceCount === 0) {
        if (isCloseUpPhoto.isTooTightlyCropped) {
          errors.push('Photo is cropped too tightly. Please use a photo that shows your head and shoulders with some background visible.');
        } else {
          errors.push('No face detected in image. Please upload a clear photo with your face visible.');
        }
      } else if (faceCount > 1) {
        if (isCloseUpPhoto.isExtremeCloseUp) {
          errors.push('Photo is too close. Please include your shoulders and back up from the camera for better results.');
        } else {
          errors.push(`Multiple faces detected (${faceCount}). Please upload photos with only yourself.`);
        }
      }

      // Body type detection
      const bodyType = await this.detectBodyType(img, detections);

      // Body type validation with improved messaging
      if (bodyType === 'full-body') {
        errors.push('Full body photo detected. Please upload headshot or upper body photos only.');
      } else if (bodyType === 'invalid') {
        if (isCloseUpPhoto.isExtremeCloseUp || isCloseUpPhoto.isTooTightlyCropped) {
          errors.push('Photo framing issue. Please use a shoulders-up photo with some space around your head.');
        } else {
          errors.push('Unable to determine photo composition. Please upload a clear headshot or upper body photo.');
        }
      } else if (bodyType === 'headshot' && (isCloseUpPhoto.isExtremeCloseUp || isCloseUpPhoto.isTooTightlyCropped)) {
        // Even though it's correctly classified as headshot, reject if it's too close/cropped
        if (isCloseUpPhoto.isExtremeCloseUp) {
          errors.push('Photo is too close. Please include your shoulders and back up from the camera for better results.');
        } else {
          errors.push('Photo is cropped too tightly. Please use a photo that shows your head and shoulders with some background visible.');
        }
      }

      // Quality scoring
      const qualityScore = await this.imageQuality.calculateQualityScore(img, detections, file);

      // Apply heavy penalties for validation failures to ensure rejected photos get low scores
      if (errors.length > 0) {
        // Photo has validation errors - apply significant penalty
        let penalty = 0;

        // Multiple faces or no faces
        if (faceCount === 0) {
          penalty = 50; // Cap at ~50
        } else if (faceCount > 1) {
          penalty = 60; // Cap at ~40
        }

        // Close-up photos
        if (isCloseUpPhoto.isExtremeCloseUp) {
          penalty = Math.max(penalty, 45); // Cap at ~55
        } else if (isCloseUpPhoto.isTooTightlyCropped) {
          penalty = Math.max(penalty, 35); // Cap at ~65
        }

        // Full-body photos  
        if (bodyType === 'full-body') {
          penalty = Math.max(penalty, 50); // Cap at ~50
        }

        // Apply the penalty
        qualityScore.overall = Math.max(20, qualityScore.overall - penalty);

        // Also reduce face quality score in breakdown
        qualityScore.breakdown.faceQuality = Math.max(0, qualityScore.breakdown.faceQuality - (penalty * 0.6));
      }

      // Quality warnings
      if (qualityScore.overall < 50) {
        warnings.push('Image quality is below recommended standards. Consider uploading a higher quality photo.');
      } else if (qualityScore.overall < 70) {
        warnings.push('Image quality could be improved for better AI results.');
      }

      const isValid = errors.length === 0 && faceCount === 1 && ['headshot', 'upper-body'].includes(bodyType);

      return {
        isValid,
        faceCount,
        bodyType,
        qualityScore,
        errors,
        warnings
      };

    } catch (error) {
      console.error('Face validation error:', error);
      return {
        isValid: false,
        faceCount: 0,
        bodyType: 'invalid',
        qualityScore: this.imageQuality.getDefaultQualityScore(),
        errors: ['Unable to analyze image. Please try a different photo.'],
        warnings: []
      };
    }
  }

  /**
   * Detect if photo is too close-up or tightly cropped
   */
  private detectCloseUpPhoto(img: HTMLImageElement, detections: faceapi.WithFaceLandmarks<any>[]): {
    isExtremeCloseUp: boolean;
    isTooTightlyCropped: boolean;
  } {
    if (detections.length === 0) {
      // No face detected - check if image might be too tightly cropped
      // This is a heuristic: very small images or extreme aspect ratios might indicate cropping issues
      const aspectRatio = img.width / img.height;
      const isTooTightlyCropped = aspectRatio > 2 || aspectRatio < 0.5 || 
                                 (img.width < 100 && img.height < 100);

      return {
        isExtremeCloseUp: false,
        isTooTightlyCropped
      };
    }

    if (detections.length === 1) {
      const detection = detections[0];
      const box = detection.detection.box;

      // Calculate face metrics
      const faceWidth = box.width;
      const faceHeight = box.height;
      const faceWidthRatio = faceWidth / img.width;
      const faceHeightRatio = faceHeight / img.height;
      const faceArea = faceWidthRatio * faceHeightRatio;

      // Check if face touches or exceeds image boundaries (with small margin)
      const margin = 10; // pixels
      const faceLeft = box.x;
      const faceRight = box.x + box.width;
      const faceTop = box.y;
      const faceBottom = box.y + box.height;

      const touchesEdges = faceLeft <= margin || 
                          faceRight >= (img.width - margin) || 
                          faceTop <= margin || 
                          faceBottom >= (img.height - margin);

      // Extreme close-up indicators
      const isExtremeCloseUp = faceHeightRatio > 0.6 || // Face takes up >60% of image height
                              faceWidthRatio > 0.7 ||   // Face takes up >70% of image width
                              faceArea > 0.45 ||        // Face area >45% of total image
                              touchesEdges;             // Face touches image edges

      // Tightly cropped indicators (face is large but not extreme)
      const isTooTightlyCropped = !isExtremeCloseUp && 
                                 (faceHeightRatio > 0.4 || faceWidthRatio > 0.5) &&
                                 touchesEdges;

      return {
        isExtremeCloseUp,
        isTooTightlyCropped
      };
    }

    // Multiple detections - might be a close-up causing false multiple face detection
    if (detections.length > 1) {
      // Check if any detected face is very large (indicating close-up)
      const hasLargeFace = detections.some(detection => {
        const box = detection.detection.box;
        const faceHeightRatio = box.height / img.height;
        const faceWidthRatio = box.width / img.width;
        return faceHeightRatio > 0.4 || faceWidthRatio > 0.5;
      });

      return {
        isExtremeCloseUp: hasLargeFace,
        isTooTightlyCropped: false
      };
    }

    return {
      isExtremeCloseUp: false,
      isTooTightlyCropped: false
    };
  }

  /**
   * Detect body type based on face position and image composition
   */
  private async detectBodyType(img: HTMLImageElement, detections: faceapi.WithFaceLandmarks<any>[]): Promise<'headshot' | 'upper-body' | 'full-body' | 'invalid'> {
    if (detections.length === 0) {
      return 'invalid';
    }

    const detection = detections[0];
    const imgHeight = img.height;
    const imgWidth = img.width;

    // Get face bounding box
    const box = detection.detection.box;
    const faceTop = box.y;
    const faceBottom = box.y + box.height;
    const faceCenter = box.y + (box.height / 2);
    const faceWidth = box.width;
    const faceHeight = box.height;

    // Calculate relative positions
    const faceTopRatio = faceTop / imgHeight;
    const faceCenterRatio = faceCenter / imgHeight;
    const faceBottomRatio = faceBottom / imgHeight;
    const faceWidthRatio = faceWidth / imgWidth;
    const faceHeightRatio = faceHeight / imgHeight;

    // First check if this is a close-up photo that should not be classified as full-body
    const closeUpCheck = this.detectCloseUpPhoto(img, detections);

    // If it's an extreme close-up or tightly cropped, it cannot be full-body
    if (closeUpCheck.isExtremeCloseUp) {
      return 'headshot'; // Very close photos are headshots by definition
    }

    if (closeUpCheck.isTooTightlyCropped) {
      return 'headshot'; // Tightly cropped photos are also headshots
    }

    // For photos with very large faces (>50% of image height), they're likely headshots
    if (faceHeightRatio > 0.5) {
      return 'headshot';
    }

    // Enhanced body type detection with multiple criteria
    const bodyTypeScore = await this.calculateBodyTypeScore(img, detection, {
      faceTopRatio,
      faceCenterRatio,
      faceBottomRatio,
      faceWidthRatio,
      faceHeightRatio,
      imgWidth,
      imgHeight
    });

    // Determine body type based on comprehensive scoring
    if (bodyTypeScore.isFullBody) {
      return 'full-body';
    } else if (bodyTypeScore.isHeadshot) {
      return 'headshot';
    } else if (bodyTypeScore.isUpperBody) {
      return 'upper-body';
    } else {
      return 'headshot'; // Default to headshot for ambiguous cases
    }
  }

  /**
   * Calculate comprehensive body type score using multiple detection methods
   */
  private async calculateBodyTypeScore(img: HTMLImageElement, detection: any, metrics: any): Promise<{
    isHeadshot: boolean;
    isUpperBody: boolean;
    isFullBody: boolean;
    confidence: number;
  }> {
    let headshotScore = 0;
    let upperBodyScore = 0;
    let fullBodyScore = 0;

    // 1. Face Position Analysis (40% weight)
    if (metrics.faceCenterRatio <= 0.25) {
      headshotScore += 40;
    } else if (metrics.faceCenterRatio <= 0.4) {
      upperBodyScore += 30;
      headshotScore += 10;
    } else if (metrics.faceCenterRatio <= 0.6) {
      upperBodyScore += 40;
    } else {
      fullBodyScore += 40;
    }

    // 2. Face Size Analysis (25% weight)
    // Larger faces typically indicate closer crops (headshots)
    if (metrics.faceHeightRatio >= 0.3) {
      headshotScore += 25;
    } else if (metrics.faceHeightRatio >= 0.15) {
      upperBodyScore += 25;
    } else if (metrics.faceHeightRatio >= 0.08) {
      upperBodyScore += 15;
      fullBodyScore += 10;
    } else {
      fullBodyScore += 25;
    }

    // 3. Image Aspect Ratio Analysis (15% weight)
    const aspectRatio = metrics.imgWidth / metrics.imgHeight;
    if (aspectRatio >= 0.7 && aspectRatio <= 1.3) {
      // Square-ish images often headshots or upper body
      headshotScore += 10;
      upperBodyScore += 5;
    } else if (aspectRatio < 0.7) {
      // Tall images might be full body
      fullBodyScore += 15;
    }

    // 4. Face-to-Image Ratio Analysis (10% weight)
    const faceArea = metrics.faceWidthRatio * metrics.faceHeightRatio;
    if (faceArea >= 0.15) {
      headshotScore += 10;
    } else if (faceArea >= 0.05) {
      upperBodyScore += 10;
    } else {
      fullBodyScore += 10;
    }

    // 5. Edge Detection for Body Boundaries (10% weight)
    try {
      const bodyBoundaryScore = await this.detectBodyBoundaries(img, detection);
      if (bodyBoundaryScore.hasLowerBodyContent) {
        fullBodyScore += 10;
      } else if (bodyBoundaryScore.hasShoulderContent) {
        upperBodyScore += 10;
      } else {
        headshotScore += 10;
      }
    } catch (error) {
      // Edge detection failed, use position fallback
      if (metrics.faceCenterRatio > 0.5) {
        fullBodyScore += 5;
      } else {
        upperBodyScore += 5;
      }
    }

    // Determine final classification
    const maxScore = Math.max(headshotScore, upperBodyScore, fullBodyScore);
    const confidence = maxScore / 100;

    return {
      isHeadshot: headshotScore === maxScore && headshotScore >= 50,
      isUpperBody: upperBodyScore === maxScore && upperBodyScore >= 40,
      isFullBody: fullBodyScore === maxScore && fullBodyScore >= 30,
      confidence
    };
  }

  /**
   * Detect body boundaries using edge detection
   */
  private async detectBodyBoundaries(img: HTMLImageElement, detection: any): Promise<{
    hasLowerBodyContent: boolean;
    hasShoulderContent: boolean;
    confidence: number;
  }> {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d')!;

    // Sample analysis region below the face
    const sampleHeight = Math.min(200, img.height);
    const sampleWidth = Math.min(200, img.width);
    canvas.width = sampleWidth;
    canvas.height = sampleHeight;

    // Focus on area below the face
    const faceBottom = detection.detection.box.y + detection.detection.box.height;
    const analysisStartY = Math.min(faceBottom, img.height * 0.3);

    ctx.drawImage(img, 0, analysisStartY, img.width, img.height - analysisStartY, 
                  0, 0, sampleWidth, sampleHeight);

    try {
      const imageData = ctx.getImageData(0, 0, sampleWidth, sampleHeight);
      const data = imageData.data;

      // Analyze content below face for body indicators
      let edgeCount = 0;
      let verticalEdges = 0;
      let horizontalEdges = 0;

      // Simple edge detection
      for (let y = 1; y < sampleHeight - 1; y++) {
        for (let x = 1; x < sampleWidth - 1; x++) {
          const idx = (y * sampleWidth + x) * 4;
          const current = (data[idx] + data[idx + 1] + data[idx + 2]) / 3;

          // Check horizontal edges (shoulders, torso)
          const right = (data[idx + 4] + data[idx + 5] + data[idx + 6]) / 3;
          const left = (data[idx - 4] + data[idx - 3] + data[idx - 2]) / 3;

          // Check vertical edges (body outline)
          const below = (data[(y + 1) * sampleWidth * 4 + x * 4] + 
                        data[(y + 1) * sampleWidth * 4 + x * 4 + 1] + 
                        data[(y + 1) * sampleWidth * 4 + x * 4 + 2]) / 3;

          if (Math.abs(current - right) > 30 || Math.abs(current - left) > 30) {
            verticalEdges++;
          }

          if (Math.abs(current - below) > 30) {
            horizontalEdges++;
          }

          if (Math.abs(current - right) > 20 || Math.abs(current - below) > 20) {
            edgeCount++;
          }
        }
      }

      const totalPixels = sampleWidth * sampleHeight;
      const edgeRatio = edgeCount / totalPixels;
      const verticalRatio = verticalEdges / totalPixels;
      const horizontalRatio = horizontalEdges / totalPixels;

      // Determine body content based on edge patterns
      const hasLowerBodyContent = edgeRatio > 0.15 && verticalRatio > 0.08;
      const hasShoulderContent = horizontalRatio > 0.05 && edgeRatio > 0.08;

      return {
        hasLowerBodyContent,
        hasShoulderContent,
        confidence: Math.min(edgeRatio * 2, 1)
      };

    } catch (error) {
      return {
        hasLowerBodyContent: false,
        hasShoulderContent: false,
        confidence: 0
      };
    }
  }

}

