import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable } from 'rxjs';
import { AuthService } from './auth.service';
import { ConfigService } from './config.service';
import { FileUploadService } from './file-upload.service';
import {
  DashboardStateForFallback,
  DataDiscrepancyResult,
  FallbackCheckResult,
  FallbackTracker,
  IFallbackOperationsService,
} from '../interfaces/service.interfaces';

@Injectable({
  providedIn: 'root',
})
export class FallbackOperationsService implements IFallbackOperationsService {
  private fallbackOperationsRun: FallbackTracker = {
    filesystemCheck: false,
    modelDiscovery: false,
    lastReset: 0,
  };

  private readonly FALLBACK_RESET_INTERVAL_MS = 300000; // 5 minutes

  constructor(
    private _http: HttpClient,
    private _authService: AuthService,
    private _config: ConfigService,
    private _fileUploadService: FileUploadService
  ) {}

  /**
   * Check filesystem for missing generated images and sync to database
   */
  checkGeneratedImagesFromFilesystem(): Observable<any> {
    const token = this._authService.getToken();
    if (!token) {
      throw new Error('No authentication token available for fix endpoint');
    }

    const headers = new HttpHeaders({
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    });

    return new Observable(observer => {
      this._http
        .post(this._config.getFullUrl('/test/fix-generated-images'), {}, { headers })
        .subscribe({
          next: (response: any) => {
            if (response.success && response.data?.addedCount > 0) {
              // Invalidate user images cache for fresh data
              this._fileUploadService.invalidateUserImagesCache();

              // Get fresh data to ensure we have the correct total count
              this._fileUploadService.getUserImages(true).subscribe({
                next: (freshData: any) => {
                  const userData = freshData.success ? freshData.data : null;
                  const actualGeneratedCount =
                    userData?.generatedImages ||
                    userData?.images?.filter((img: any) => img.isGenerated)?.length ||
                    0;

                  observer.next({
                    success: true,
                    addedCount: response.data.addedCount,
                    actualGeneratedCount,
                  });
                  observer.complete();
                },
                error: (error: any) => {
                  console.error('Failed to refresh generated photos count after fix:', error);
                  observer.error(error);
                },
              });
            } else {
              observer.next({ success: true, addedCount: 0 });
              observer.complete();
            }
          },
          error: error => {
            console.error('❌ Failed to check/fix generated images from filesystem:', error);
            observer.error(error);
          },
        });
    });
  }

  /**
   * Check if filesystem fallback is needed
   */
  isFilesystemCheckNeeded(
    generatedPhotosCount: number,
    hasTrainedModel: boolean,
    userProfile: any
  ): boolean {
    return (
      generatedPhotosCount === 0 &&
      (hasTrainedModel || userProfile?.latestTrainedModel) &&
      userProfile && // User has been active
      !this.fallbackOperationsRun.filesystemCheck
    );
  }

  /**
   * Check if model discovery is needed
   */
  isModelDiscoveryNeeded(
    modelStatus: string,
    uploadedImages: number,
    hasTrainedModel: boolean
  ): boolean {
    return (
      modelStatus === 'Not Started' &&
      uploadedImages > 0 &&
      !hasTrainedModel &&
      !this.fallbackOperationsRun.modelDiscovery
    );
  }

  /**
   * Intelligent fallback operations - only run when actually needed
   */
  checkIfFallbackNeeded(state: DashboardStateForFallback): FallbackCheckResult {
    // Check filesystem if we have 0 photos but evidence of a trained model
    const shouldCheckFilesystem =
      state.generatedPhotosCount === 0 &&
      (state.latestTrainedModel || state.modelStatus === 'Model Ready') &&
      state.hasUserProfile && // User has been active
      !this.fallbackOperationsRun.filesystemCheck;

    // Discover models if we're missing model data but have uploads
    const shouldDiscoverModels =
      state.modelStatus === 'Not Started' &&
      state.uploadedImages > 0 &&
      !state.latestTrainedModel &&
      !this.fallbackOperationsRun.modelDiscovery;

    if (shouldCheckFilesystem) {
      this.fallbackOperationsRun.filesystemCheck = true;
    }

    if (shouldDiscoverModels) {
      this.fallbackOperationsRun.modelDiscovery = true;
    }

    if (!shouldCheckFilesystem && !shouldDiscoverModels) {
    }

    return { shouldCheckFilesystem, shouldDiscoverModels };
  }

  /**
   * Debug method to check actual data vs displayed data
   */
  async debugDataDiscrepancy(): Promise<DataDiscrepancyResult> {
    try {
      const freshData = await this._fileUploadService.getUserImages(true).toPromise();
      const userData = freshData?.success ? freshData.data : null;

      const result: DataDiscrepancyResult = {
        dashboardCount: 0, // This would be passed from dashboard state
        apiGeneratedField: userData?.generatedImages || 0,
        filteredCount: userData?.images?.filter((img: any) => img.isGenerated)?.length || 0,
        totalImages: userData?.totalImages || 0,
        allImages: userData?.images || [],
      };

      return result;
    } catch (error) {
      console.error('Failed to debug data discrepancy:', error);
      throw error;
    }
  }

  /**
   * Reset fallback tracking to allow fresh attempts
   */
  resetFallbackTracking(): void {
    const now = Date.now();

    // Reset fallback tracking every 5 minutes to allow fresh attempts
    if (now - this.fallbackOperationsRun.lastReset > this.FALLBACK_RESET_INTERVAL_MS) {
      this.fallbackOperationsRun = {
        filesystemCheck: false,
        modelDiscovery: false,
        lastReset: now,
      };
    }
  }

  /**
   * Get current fallback tracker state
   */
  getFallbackTracker(): FallbackTracker {
    return { ...this.fallbackOperationsRun };
  }

  /**
   * Mark filesystem check as completed
   */
  markFilesystemCheckCompleted(): void {
    this.fallbackOperationsRun.filesystemCheck = true;
  }

  /**
   * Mark model discovery as completed
   */
  markModelDiscoveryCompleted(): void {
    this.fallbackOperationsRun.modelDiscovery = true;
  }
}

import { Injectable } from '@angular/core';
import { Observable, of, throwError } from 'rxjs';

export interface FileSecurityValidation {
  isValid: boolean;
  securityIssues: string[];
  sanitizedFile?: File;
  riskLevel: 'low' | 'medium' | 'high' | 'critical';
}

export interface SecurityConfig {
  maxFileSize: number; // bytes
  allowedMimeTypes: string[];
  allowedExtensions: string[];
  maxFilesPerUpload: number;
  maxTotalSize: number;
  scanForMaliciousContent: boolean;
  validateFileHeaders: boolean;
}

/**
 * Service responsible for file upload security validation and sanitization
 * Implements OWASP recommendations for secure file uploads
 */
@Injectable({
  providedIn: 'root',
})
export class FileSecurityService {
  private readonly DEFAULT_CONFIG: SecurityConfig = {
    maxFileSize: 10 * 1024 * 1024, // 10MB
    allowedMimeTypes: [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
      'image/heic',
      'image/heif',
    ],
    allowedExtensions: ['.jpg', '.jpeg', '.png', '.webp', '.heic', '.heif'],
    maxFilesPerUpload: 20,
    maxTotalSize: 100 * 1024 * 1024, // 100MB total
    scanForMaliciousContent: true,
    validateFileHeaders: true,
  };

  private config: SecurityConfig = { ...this.DEFAULT_CONFIG };

  /**
   * Validate a single file against security policies
   */
  validateFile(file: File): Observable<FileSecurityValidation> {
    const validation: FileSecurityValidation = {
      isValid: true,
      securityIssues: [],
      riskLevel: 'low',
    };

    try {
      // 1. File size validation
      if (file.size > this.config.maxFileSize) {
        validation.isValid = false;
        validation.securityIssues.push(
          `File size ${this.formatFileSize(file.size)} exceeds maximum allowed size ${this.formatFileSize(this.config.maxFileSize)}`
        );
        validation.riskLevel = 'medium';
      }

      // 2. Empty file check
      if (file.size === 0) {
        validation.isValid = false;
        validation.securityIssues.push('Empty files are not allowed');
        validation.riskLevel = 'high';
      }

      // 3. MIME type validation
      if (!this.config.allowedMimeTypes.includes(file.type)) {
        validation.isValid = false;
        validation.securityIssues.push(`File type '${file.type}' is not allowed`);
        validation.riskLevel = 'high';
      }

      // 4. File extension validation
      const extension = this.getFileExtension(file.name).toLowerCase();
      if (!this.config.allowedExtensions.includes(extension)) {
        validation.isValid = false;
        validation.securityIssues.push(`File extension '${extension}' is not allowed`);
        validation.riskLevel = 'high';
      }

      // 5. Filename validation (prevent path traversal)
      if (this.containsPathTraversal(file.name)) {
        validation.isValid = false;
        validation.securityIssues.push('Filename contains potentially dangerous path characters');
        validation.riskLevel = 'critical';
      }

      // 6. Dangerous filename patterns
      if (this.hasDangerousFilename(file.name)) {
        validation.isValid = false;
        validation.securityIssues.push('Filename matches dangerous pattern');
        validation.riskLevel = 'critical';
      }

      // 7. MIME type vs extension mismatch
      if (!this.validateMimeExtensionMatch(file.type, extension)) {
        validation.isValid = false;
        validation.securityIssues.push('File type and extension do not match');
        validation.riskLevel = 'high';
      }

      return of(validation);
    } catch (error) {
      validation.isValid = false;
      validation.securityIssues.push('File validation failed due to internal error');
      validation.riskLevel = 'critical';
      return of(validation);
    }
  }

  /**
   * Validate multiple files as a batch
   */
  validateFiles(files: File[]): Observable<{
    isValid: boolean;
    fileValidations: FileSecurityValidation[];
    batchIssues: string[];
    totalSize: number;
  }> {
    if (files.length === 0) {
      return of({
        isValid: false,
        fileValidations: [],
        batchIssues: ['No files provided for validation'],
        totalSize: 0,
      });
    }

    // Check batch limits
    const batchIssues: string[] = [];
    let batchValid = true;

    if (files.length > this.config.maxFilesPerUpload) {
      batchValid = false;
      batchIssues.push(
        `Too many files: ${files.length} exceeds maximum of ${this.config.maxFilesPerUpload}`
      );
    }

    const totalSize = files.reduce((sum, file) => sum + file.size, 0);
    if (totalSize > this.config.maxTotalSize) {
      batchValid = false;
      batchIssues.push(
        `Total size ${this.formatFileSize(totalSize)} exceeds maximum ${this.formatFileSize(this.config.maxTotalSize)}`
      );
    }

    // Validate individual files
    const fileValidations: FileSecurityValidation[] = [];
    for (const file of files) {
      const validation = this.validateFileSynchronously(file);
      fileValidations.push(validation);
      if (!validation.isValid) {
        batchValid = false;
      }
    }

    return of({
      isValid: batchValid,
      fileValidations,
      batchIssues,
      totalSize,
    });
  }

  /**
   * Sanitize filename to prevent security issues
   */
  sanitizeFilename(filename: string): string {
    // Remove path traversal attempts
    let sanitized = filename.replace(/[\/\\\.]{2,}/g, '');

    // Remove dangerous characters
    sanitized = sanitized.replace(/[<>:"|?*\x00-\x1f]/g, '_');

    // Limit length
    if (sanitized.length > 255) {
      const extension = this.getFileExtension(sanitized);
      const nameOnly = sanitized.substring(0, sanitized.lastIndexOf('.'));
      sanitized = nameOnly.substring(0, 255 - extension.length) + extension;
    }

    // Ensure it doesn't start with dangerous patterns
    if (/^(con|prn|aux|nul|com[1-9]|lpt[1-9])$/i.test(sanitized.split('.')[0])) {
      sanitized = 'file_' + sanitized;
    }

    return sanitized;
  }

  /**
   * Advanced file header validation to detect file type spoofing
   */
  async validateFileHeaders(
    file: File
  ): Promise<{ isValid: boolean; detectedType: string; issues: string[] }> {
    if (!this.config.validateFileHeaders) {
      return { isValid: true, detectedType: file.type, issues: [] };
    }

    try {
      const buffer = await this.readFileBuffer(file, 12); // Read first 12 bytes for magic numbers
      const signature = Array.from(new Uint8Array(buffer))
        .map(byte => byte.toString(16).padStart(2, '0'))
        .join('');

      const detectedType = this.detectFileTypeFromSignature(signature);
      const issues: string[] = [];

      if (detectedType && detectedType !== file.type) {
        issues.push(`File header indicates ${detectedType} but MIME type is ${file.type}`);
        return { isValid: false, detectedType, issues };
      }

      return { isValid: true, detectedType: detectedType || file.type, issues: [] };
    } catch (error) {
      return {
        isValid: false,
        detectedType: 'unknown',
        issues: ['Failed to read file headers'],
      };
    }
  }

  /**
   * Update security configuration
   */
  updateConfig(newConfig: Partial<SecurityConfig>): void {
    this.config = { ...this.config, ...newConfig };
    console.log('🔒 File security configuration updated:', this.config);
  }

  /**
   * Get current security configuration
   */
  getConfig(): Readonly<SecurityConfig> {
    return { ...this.config };
  }

  // Private helper methods

  private validateFileSynchronously(file: File): FileSecurityValidation {
    const validation: FileSecurityValidation = {
      isValid: true,
      securityIssues: [],
      riskLevel: 'low',
    };

    // File size validation
    if (file.size > this.config.maxFileSize) {
      validation.isValid = false;
      validation.securityIssues.push('File too large');
      validation.riskLevel = 'medium';
    }

    // MIME type validation
    if (!this.config.allowedMimeTypes.includes(file.type)) {
      validation.isValid = false;
      validation.securityIssues.push('Invalid file type');
      validation.riskLevel = 'high';
    }

    // Extension validation
    const extension = this.getFileExtension(file.name).toLowerCase();
    if (!this.config.allowedExtensions.includes(extension)) {
      validation.isValid = false;
      validation.securityIssues.push('Invalid file extension');
      validation.riskLevel = 'high';
    }

    return validation;
  }

  private getFileExtension(filename: string): string {
    const lastDot = filename.lastIndexOf('.');
    return lastDot >= 0 ? filename.substring(lastDot) : '';
  }

  private containsPathTraversal(filename: string): boolean {
    return /\.\.\/|\.\.\\|\/\.\.|\\\.\./.test(filename);
  }

  private hasDangerousFilename(filename: string): boolean {
    const dangerousPatterns = [
      /^\./, // Hidden files
      /\.(exe|bat|cmd|scr|pif|com|dll|vbs|js|jar|sh)$/i, // Executable extensions
      /^(thumbs\.db|desktop\.ini|\$recycle\.bin)$/i, // System files
    ];

    return dangerousPatterns.some(pattern => pattern.test(filename));
  }

  private validateMimeExtensionMatch(mimeType: string, extension: string): boolean {
    const mimeExtensionMap: Record<string, string[]> = {
      'image/jpeg': ['.jpg', '.jpeg'],
      'image/png': ['.png'],
      'image/webp': ['.webp'],
      'image/heic': ['.heic'],
      'image/heif': ['.heif'],
    };

    const validExtensions = mimeExtensionMap[mimeType];
    return validExtensions ? validExtensions.includes(extension) : false;
  }

  private async readFileBuffer(file: File, bytes: number): Promise<ArrayBuffer> {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as ArrayBuffer);
      reader.onerror = () => reject(reader.error);
      reader.readAsArrayBuffer(file.slice(0, bytes));
    });
  }

  private detectFileTypeFromSignature(signature: string): string | null {
    const signatures: Record<string, string> = {
      ffd8ff: 'image/jpeg',
      '89504e47': 'image/png',
      '52494646': 'image/webp', // Partial - WebP starts with RIFF
      '00000018667479': 'image/heic', // HEIC signature is more complex
      '00000020667479': 'image/heif',
    };

    for (const [sig, type] of Object.entries(signatures)) {
      if (signature.startsWith(sig)) {
        return type;
      }
    }

    return null;
  }

  private formatFileSize(bytes: number): string {
    if (bytes === 0) {return '0 B';}
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return `${parseFloat((bytes / Math.pow(k, i)).toFixed(1))} ${sizes[i]}`;
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { FaceDetectionService } from './face-detection.service';
import { FaceValidationResult, QualityScore } from '../interfaces/service.interfaces';
import { QualityCheckError, QualityCheckResult, SelectedFileWithQuality, UploadProgress } from '../models/dashboard.types';

@Injectable({
  providedIn: 'root'
})
export class FileUploadManagerService {
  private uploadProgressSubject = new BehaviorSubject<UploadProgress>({ percentage: 0 });
  public uploadProgress$ = this.uploadProgressSubject.asObservable();

  private selectedFilesSubject = new BehaviorSubject<SelectedFileWithQuality[]>([]);
  public selectedFiles$ = this.selectedFilesSubject.asObservable();

  constructor(private faceDetectionService: FaceDetectionService) {}

  async processFiles(files: FileList): Promise<QualityCheckResult> {
    const validFiles: File[] = [];
    const errorFiles: QualityCheckError[] = [];
    const selectedFiles: SelectedFileWithQuality[] = [];

    for (let i = 0; i < files.length; i++) {
      const file = files[i];

      // Update progress
      this.uploadProgressSubject.next({
        percentage: Math.round((i / files.length) * 50), // 50% for processing
        currentFile: file.name,
        totalFiles: files.length
      });

      try {
        const qualityResult = await this.validateFile(file);

        if (qualityResult.errors.length === 0) {
          validFiles.push(file);
        } else {
          errorFiles.push({
            fileName: file.name,
            file,
            errors: qualityResult.errors,
            warnings: qualityResult.warnings,
            faceValidation: qualityResult.faceValidation,
            qualityScore: qualityResult.qualityScore
          });
        }

        selectedFiles.push(qualityResult);
      } catch (error) {
        errorFiles.push({
          fileName: file.name,
          file,
          errors: [`Failed to process file: ${error}`]
        });
      }
    }

    this.selectedFilesSubject.next(selectedFiles);

    // Complete processing
    this.uploadProgressSubject.next({
      percentage: 100,
      completed: true
    });

    return { validFiles, invalidFiles: errorFiles.map(e => e.file), errors: errorFiles, totalProcessed: files.length };
  }

  private async validateFile(file: File): Promise<SelectedFileWithQuality> {
    const errors: string[] = [];
    const warnings: string[] = [];

    // Basic file validation
    if (!file.type.startsWith('image/')) {
      errors.push('File must be an image');
    }

    if (file.size > 10 * 1024 * 1024) { // 10MB limit
      errors.push('File size must be less than 10MB');
    }

    // Face detection and quality analysis
    let faceValidation: FaceValidationResult | undefined;

    try {
      faceValidation = await this.faceDetectionService.validateImage(file);

      // Validate face requirements
      if (faceValidation && faceValidation.faceCount === 0) {
        errors.push('No face detected in the image');
      } else if (faceValidation && faceValidation.faceCount > 1) {
        errors.push('Multiple faces detected. Please use images with only one person');
      }

      // Quality warnings from faceValidation.qualityScore
      const qualityScore = faceValidation?.qualityScore;
      if (qualityScore && qualityScore.overall < 70) {
        warnings.push('Image quality could be improved for better results');
      }

      if (qualityScore && qualityScore.breakdown.technical < 60) {
        warnings.push('Image appears blurry or low quality. Sharper images produce better results');
      }

      if (qualityScore && qualityScore.breakdown.lighting < 60) {
        warnings.push('Lighting could be improved for better results');
      }

    } catch (error) {
      warnings.push('Could not analyze image quality');
    }

    return {
      file,
      qualityScore: faceValidation?.qualityScore,
      faceValidation,
      errors,
      warnings,
      isValid: errors.length === 0,
      showDetails: false
    };
  }

  clearFiles() {
    this.selectedFilesSubject.next([]);
    this.uploadProgressSubject.next({ percentage: 0 });
  }

  removeFile(fileToRemove: File) {
    const currentFiles = this.selectedFilesSubject.value;
    const updatedFiles = currentFiles.filter(f => f.file !== fileToRemove);
    this.selectedFilesSubject.next(updatedFiles);
  }

  getValidFiles(): File[] {
    return this.selectedFilesSubject.value
      .filter(f => f.isValid)
      .map(f => f.file);
  }

  hasValidFiles(): boolean {
    return this.getValidFiles().length > 0;
  }

  getFileCount(): number {
    return this.selectedFilesSubject.value.length;
  }

  getValidFileCount(): number {
    return this.getValidFiles().length;
  }
}

