import { Injectable, NgZone } from '@angular/core';
import * as faceapi from 'face-api.js';
import { IImageQualityService, QualityScore } from '../interfaces/service.interfaces';

@Injectable({
  providedIn: 'root'
})
export class ImageQualityService implements IImageQualityService {

  constructor(private ngZone: NgZone) {}

  /**
   * Calculate comprehensive quality score
   */
  async calculateQualityScore(img: HTMLImageElement, detections: faceapi.WithFaceLandmarks<any>[], file: File): Promise<QualityScore> {
    const scores = {
      faceQuality: 0,
      technical: 0,
      composition: 0,
      fluxCompatibility: 0,
      lighting: 0
    };

    const suggestions: string[] = [];

    // 1. Face Quality (30 points)
    if (detections.length === 1) {
      const detection = detections[0];
      const confidence = detection.detection.score;

      scores.faceQuality = Math.min(30, confidence * 30);

      if (confidence < 0.7) {
        suggestions.push('Face is not clearly visible. Try better lighting or camera angle.');
      }
    } else {
      suggestions.push('Upload photo with exactly one clearly visible face.');
    }

    // 2. Technical Quality (25 points)
    const techScore = await this.assessTechnicalQuality(img, file);
    scores.technical = techScore.score;
    suggestions.push(...techScore.suggestions);

    // 3. Composition (20 points)
    const compScore = this.assessComposition(img, detections);
    scores.composition = compScore.score;
    suggestions.push(...compScore.suggestions);

    // 4. FLUX Compatibility (15 points)
    const fluxScore = await this.assessFluxCompatibility(img);
    scores.fluxCompatibility = fluxScore.score;
    suggestions.push(...fluxScore.suggestions);

    // 5. Lighting (10 points)
    const lightScore = this.assessLighting(img);
    scores.lighting = lightScore.score;
    suggestions.push(...lightScore.suggestions);

    const overall = Math.round(
      scores.faceQuality + 
      scores.technical + 
      scores.composition + 
      scores.fluxCompatibility + 
      scores.lighting
    );

    return {
      overall: Math.max(1, Math.min(100, overall)),
      breakdown: scores,
      suggestions: suggestions.filter(s => s.length > 0)
    };
  }

  /**
   * Assess technical image quality
   */
  private async assessTechnicalQuality(img: HTMLImageElement, file: File): Promise<{score: number, suggestions: string[]}> {
    const suggestions: string[] = [];
    let score = 0;

    // Resolution check (10 points)
    const minRes = 512;
    const idealRes = 1024;

    if (img.width >= idealRes && img.height >= idealRes) {
      score += 10;
    } else if (img.width >= minRes && img.height >= minRes) {
      score += 7;
      suggestions.push('Higher resolution image (1024x1024+) recommended for best results.');
    } else {
      score += 3;
      suggestions.push('Image resolution is too low. Upload higher quality image.');
    }

    // File size check (5 points)
    const fileSizeMB = file.size / (1024 * 1024);
    if (fileSizeMB > 0.5 && fileSizeMB <= 7) {
      score += 5;
    } else if (fileSizeMB <= 0.5) {
      score += 2;
      suggestions.push('File size is small, which may indicate low quality.');
    }

    // Blur detection (10 points)
    const blurScore = await this.detectBlur(img);
    score += blurScore;

    if (blurScore < 5) {
      suggestions.push('Image appears blurry. Use better focus or lighting.');
    }

    return { score, suggestions };
  }

  /**
   * Assess image composition
   */
  private assessComposition(img: HTMLImageElement, detections: faceapi.WithFaceLandmarks<any>[]): {score: number, suggestions: string[]} {
    const suggestions: string[] = [];
    let score = 0;

    if (detections.length === 1) {
      const detection = detections[0];
      const box = detection.detection.box;

      // Face positioning (10 points)
      const faceCenterX = (box.x + box.width / 2) / img.width;
      const faceCenterY = (box.y + box.height / 2) / img.height;

      // Check if face is roughly centered
      if (faceCenterX >= 0.3 && faceCenterX <= 0.7) {
        score += 5;
      } else {
        suggestions.push('Center your face in the photo for better composition.');
      }

      if (faceCenterY >= 0.2 && faceCenterY <= 0.6) {
        score += 5;
      } else {
        suggestions.push('Position your face in the upper portion of the photo.');
      }

      // Face size (10 points)
      const faceArea = (box.width * box.height) / (img.width * img.height);
      if (faceArea >= 0.1 && faceArea <= 0.4) {
        score += 10;
      } else if (faceArea < 0.1) {
        score += 5;
        suggestions.push('Move closer to camera or crop tighter for better face visibility.');
      } else {
        score += 7;
        suggestions.push('Face takes up a lot of the frame. Consider backing up slightly.');
      }
    } else {
      suggestions.push('Composition cannot be assessed without a clear single face.');
    }

    return { score, suggestions };
  }

  /**
   * Assess FLUX AI compatibility
   */
  private async assessFluxCompatibility(img: HTMLImageElement): Promise<{score: number, suggestions: string[]}> {
    const suggestions: string[] = [];
    let score = 10; // Start optimistic

    // Check for common FLUX negative prompt issues
    // This is a simplified assessment - could be enhanced with ML models

    // Basic image quality indicators
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d')!;
    canvas.width = img.width;
    canvas.height = img.height;
    ctx.drawImage(img, 0, 0);

    try {
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;

      // Check for overexposure/underexposure
      let brightPixels = 0;
      let darkPixels = 0;

      for (let i = 0; i < data.length; i += 4) {
        const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
        if (avg > 240) {brightPixels++;}
        if (avg < 15) {darkPixels++;}
      }

      const totalPixels = data.length / 4;
      const brightRatio = brightPixels / totalPixels;
      const darkRatio = darkPixels / totalPixels;

      if (brightRatio > 0.3) {
        score -= 3;
        suggestions.push('Image appears overexposed. Reduce lighting or use better camera settings.');
      }

      if (darkRatio > 0.3) {
        score -= 3;
        suggestions.push('Image appears underexposed. Increase lighting for better visibility.');
      }

    } catch (error) {
      // Canvas analysis failed, use default score
    }

    return { score: Math.max(0, score), suggestions };
  }

  /**
   * Assess lighting quality
   */
  private assessLighting(img: HTMLImageElement): {score: number, suggestions: string[]} {
    const suggestions: string[] = [];
    let score = 8; // Start with good score

    // Basic lighting assessment using canvas analysis
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d')!;
    canvas.width = Math.min(img.width, 200); // Sample for performance
    canvas.height = Math.min(img.height, 200);
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

    try {
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;

      let totalBrightness = 0;
      for (let i = 0; i < data.length; i += 4) {
        totalBrightness += (data[i] + data[i + 1] + data[i + 2]) / 3;
      }

      const avgBrightness = totalBrightness / (data.length / 4);

      if (avgBrightness < 50) {
        score -= 4;
        suggestions.push('Image is too dark. Use better lighting for clearer results.');
      } else if (avgBrightness > 200) {
        score -= 3;
        suggestions.push('Image is too bright. Reduce harsh lighting or exposure.');
      } else if (avgBrightness >= 80 && avgBrightness <= 180) {
        score += 2; // Bonus for good lighting
      }

    } catch (error) {
      // Lighting analysis failed
      suggestions.push('Unable to assess lighting quality.');
    }

    return { score: Math.max(0, Math.min(10, score)), suggestions };
  }

  /**
   * Detect image blur using Laplacian variance
   */
  private async detectBlur(img: HTMLImageElement): Promise<number> {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d')!;

    // Sample size for performance
    const sampleSize = 100;
    canvas.width = sampleSize;
    canvas.height = sampleSize;

    ctx.drawImage(img, 0, 0, sampleSize, sampleSize);

    try {
      const imageData = ctx.getImageData(0, 0, sampleSize, sampleSize);
      const data = imageData.data;

      // Convert to grayscale and apply Laplacian operator
      let variance = 0;
      const laplacian = [];

      // Simplified blur detection
      for (let y = 1; y < sampleSize - 1; y++) {
        for (let x = 1; x < sampleSize - 1; x++) {
          const idx = (y * sampleSize + x) * 4;
          const gray = (data[idx] + data[idx + 1] + data[idx + 2]) / 3;

          // Simple edge detection
          const neighbors = [
            (data[(y-1) * sampleSize * 4 + x * 4] + data[(y-1) * sampleSize * 4 + x * 4 + 1] + data[(y-1) * sampleSize * 4 + x * 4 + 2]) / 3,
            (data[(y+1) * sampleSize * 4 + x * 4] + data[(y+1) * sampleSize * 4 + x * 4 + 1] + data[(y+1) * sampleSize * 4 + x * 4 + 2]) / 3,
            (data[y * sampleSize * 4 + (x-1) * 4] + data[y * sampleSize * 4 + (x-1) * 4 + 1] + data[y * sampleSize * 4 + (x-1) * 4 + 2]) / 3,
            (data[y * sampleSize * 4 + (x+1) * 4] + data[y * sampleSize * 4 + (x+1) * 4 + 1] + data[y * sampleSize * 4 + (x+1) * 4 + 2]) / 3
          ];

          const laplacianValue = Math.abs(4 * gray - neighbors.reduce((a, b) => a + b, 0));
          laplacian.push(laplacianValue);
        }
      }

      // Calculate variance
      const mean = laplacian.reduce((a, b) => a + b, 0) / laplacian.length;
      variance = laplacian.reduce((acc, val) => acc + Math.pow(val - mean, 2), 0) / laplacian.length;

      // Convert to 0-10 score (higher variance = less blur = higher score)
      return Math.min(10, Math.max(0, (variance / 100) * 10));

    } catch (error) {
      return 5; // Default medium score if analysis fails
    }
  }

  /**
   * Load image file as HTMLImageElement
   */
  loadImageElement(file: File): Promise<HTMLImageElement> {
    return new Promise((resolve, reject) => {
      this.ngZone.runOutsideAngular(() => {
        const img = new Image();
        img.onload = () => {
          this.ngZone.run(() => {
            resolve(img);
          });
        };
        img.onerror = () => {
          this.ngZone.run(() => {
            reject(new Error('Failed to load image'));
          });
        };
        img.src = URL.createObjectURL(file);
      });
    });
  }

  /**
   * Get default quality score for error cases
   */
  getDefaultQualityScore(): QualityScore {
    return {
      overall: 1,
      breakdown: {
        faceQuality: 0,
        technical: 0,
        composition: 0,
        fluxCompatibility: 0,
        lighting: 0
      },
      suggestions: ['Unable to analyze image quality. Please try a different photo.']
    };
  }
}

import { Injectable } from '@angular/core';
import { Observable, of } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { StateBaseService } from './state-base.service';
import { FileUploadService } from './file-upload.service';
import { ImageValidationService } from './image-validation.service';
import { ConfigService } from './config.service';
import { CacheManagerService } from './cache-manager.service';
import { NotificationService } from './notification.service';
import { UploadedImageThumbnail } from '../interfaces/service.interfaces';

export interface ImageState {
  uploadedImages: number;
  uploadedImageThumbnails: UploadedImageThumbnail[];
  generatedPhotosCount: number;
  isLoading: boolean;
  imagesValidated: boolean;
  lastValidationTime: number;
}

export interface ImageValidationResult {
  validImages: UploadedImageThumbnail[];
  removedCount: number;
  repairTriggered?: boolean;
}

/**
 * Service responsible for managing image state, validation, and thumbnails
 * Extracted from DashboardStateService for better separation of concerns
 */
@Injectable({
  providedIn: 'root',
})
export class ImageStateService extends StateBaseService<ImageState> {
  private readonly CACHE_KEY = 'image_state_data';
  private readonly VALIDATION_TTL = 5 * 60 * 1000; // 5 minutes


  constructor(
    _cacheManager: CacheManagerService,
    _notificationService: NotificationService,
    private _fileUploadService: FileUploadService,
    private _imageValidation: ImageValidationService,
    private _configService: ConfigService
  ) {
    super(
      {
        uploadedImages: 0,
        uploadedImageThumbnails: [],
        generatedPhotosCount: 0,
        isLoading: false,
        imagesValidated: false,
        lastValidationTime: 0,
      },
      _cacheManager,
      _notificationService
    );
  }

  /**
   * Load user images and process them into thumbnails
   */
  async loadUserImages(forceRefresh = false): Promise<void> {
    const startTime = performance.now();

    // Check cache first
    if (!forceRefresh) {
      const cachedData = this.getCachedData<ImageState>(this.CACHE_KEY);
      if (cachedData?.uploadedImageThumbnails) {
        this.setState(cachedData);

        // Always validate cached images
        if (cachedData.uploadedImageThumbnails.length > 0) {
          await this.validateCachedImages(cachedData.uploadedImageThumbnails);
        }
        return;
      }
    }

    // Debounce rapid reloads
    if (this.shouldDebounceRequest('image_load')) {
      return;
    }

    this.setLoading(true);

    try {
      const userImages = await this._fileUploadService.getUserImages(forceRefresh).toPromise();

      if (userImages?.success && userImages.data) {
        const processed = this.processUserImagesData(userImages.data);

        this.setState({
          uploadedImages: processed.uploadedImages,
          uploadedImageThumbnails: processed.uploadedImageThumbnails,
          generatedPhotosCount: processed.generatedPhotosCount,
          isLoading: false,
        });

        // Cache the processed data
        this.setCachedData(this.CACHE_KEY, this.getState());

        // Validate images if we have any
        if (processed.uploadedImageThumbnails.length > 0) {
          const validation = await this.validateAndCleanupImages(
            processed.uploadedImageThumbnails,
            false
          );
          if (validation.removedCount > 0) {
            this.updateStateWithValidatedImages(validation);
          }
        }

        this.logPerformance('User images loaded', startTime);
      } else {
        throw new Error('Failed to load user images');
      }
    } catch (error) {
      this.handleApiError(error, 'Load Images');
      this.setLoading(false);
    }
  }

  /**
   * Process raw user images data into structured format
   */
  private processUserImagesData(userImagesData: any): {
    uploadedImages: number;
    uploadedImageThumbnails: UploadedImageThumbnail[];
    generatedPhotosCount: number;
  } {
    // Process uploaded images with robust filtering
    const rawImageThumbnails: UploadedImageThumbnail[] =
      userImagesData?.images
        ?.filter((img: any) => {
          // Skip generated images entirely
          if (img.isGenerated) {
            return false;
          }

          // Robust filtering for uploaded images
          const isOriginalByFlag = img.isOriginalUpload;
          const isOriginalByStyle = img.style === 'Original';
          const hasUrl = !!img.originalImageUrl;

          const isUploadedImage = (isOriginalByFlag || isOriginalByStyle) && hasUrl;

          // Flag/style mismatch indicates possible database corruption
          if (isOriginalByFlag !== isOriginalByStyle) {
            console.warn(
              `⚠️ Image ${img.id} has flag/style mismatch: isOriginalUpload=${isOriginalByFlag}, style=${img.style} - possible database corruption`
            );
          }

          return isUploadedImage;
        })
        ?.map((img: any) => ({
          id: img.id,
          url: this.cleanImageUrl(img.originalImageUrl),
          fileName: `Image ${img.id}`,
        })) || [];

    // Count generated photos
    const generatedPhotosCount =
      userImagesData?.generatedImages ||
      userImagesData?.images?.filter((img: any) => img.isGenerated)?.length ||
      0;

    return {
      uploadedImages: rawImageThumbnails.length,
      uploadedImageThumbnails: rawImageThumbnails,
      generatedPhotosCount,
    };
  }

  /**
   * Validate cached images and update if needed
   */
  private async validateCachedImages(images: UploadedImageThumbnail[]): Promise<void> {
    const currentState = this.getState();
    const validationAge = Date.now() - (currentState.lastValidationTime || 0);

    if (currentState.imagesValidated && validationAge < this.VALIDATION_TTL) {
      return;
    }
    const result = await this.validateAndCleanupImages(images, true);

    if (result.removedCount > 0) {
      this.updateStateWithValidatedImages(result);
    } else {
      this.setState({
        imagesValidated: true,
        lastValidationTime: Date.now(),
      });
    }
  }

  /**
   * Validate and cleanup broken images
   */
  async validateAndCleanupImages(
    images: UploadedImageThumbnail[],
    isFromCache: boolean
  ): Promise<ImageValidationResult> {
    // Check if image validation is disabled via environment configuration
    if (!this._configService.isImageValidationEnabled) {
      return {
        validImages: images,
        removedCount: 0,
        repairTriggered: false,
      };
    }

    const validation = await this._imageValidation.filterValidImages(images);

    if (validation.removedCount > 0) {
      // Trigger repair if 404s were found
      if (validation.repairSuggested && validation.notFoundCount > 0) {
        try {
          const repairResult = await this._fileUploadService.repairImageDatabase().toPromise();
          if (repairResult?.success) {
            // Force refresh from server after repair
            await this.forceRefreshAfterRepair();

            return {
              validImages: validation.validImages,
              removedCount: validation.removedCount,
              repairTriggered: true,
            };
          }
        } catch (repairError) {
          console.error('🔧 Database repair failed:', repairError);
        }
      }
    }

    return {
      validImages: validation.validImages,
      removedCount: validation.removedCount,
      repairTriggered: false,
    };
  }

  /**
   * Update state with validated images
   */
  private updateStateWithValidatedImages(result: ImageValidationResult): void {
    this.setState({
      uploadedImageThumbnails: result.validImages,
      uploadedImages: result.validImages.length,
      imagesValidated: true,
      lastValidationTime: Date.now(),
    });

    // Invalidate cache since we have new data
    this.invalidateCache(this.CACHE_KEY);

    // Show notification if images were removed
    if (result.removedCount > 0) {
      const message = result.repairTriggered
        ? `Removed ${result.removedCount} broken image reference(s) and repaired database inconsistencies.`
        : `Removed ${result.removedCount} broken image reference(s) that could no longer be loaded.`;

      this.showInfo(
        result.repairTriggered ? 'Cleaned up & Repaired' : 'Cleaned up broken images',
        message
      );
    }
  }

  /**
   * Force refresh after repair to sync counts
   */
  private async forceRefreshAfterRepair(): Promise<void> {
    try {
      // Clear all caches
      this.forceRefreshCache(this.CACHE_KEY);
      this._fileUploadService.invalidateUserImagesCache();
      this._imageValidation.clearCache();

      // Get fresh data from server
      const userImages = await this._fileUploadService.getUserImages(true).toPromise();

      if (userImages?.success && userImages.data) {
        const processed = this.processUserImagesData(userImages.data);

        this.setState({
          uploadedImageThumbnails: processed.uploadedImageThumbnails,
          uploadedImages: processed.uploadedImages,
          generatedPhotosCount: processed.generatedPhotosCount,
          imagesValidated: false, // Force validation on fresh data
          lastValidationTime: 0,
        });
      }
    } catch (error) {
      console.error('❌ Failed to refresh after repair:', error);
    }
  }

  /**
   * Refresh only the generated photos count
   */
  async refreshGeneratedPhotosCount(): Promise<void> {
    try {
      const userImages = await this._fileUploadService.getUserImages().toPromise();

      if (userImages?.success && userImages.data) {
        const userImagesData = userImages.data;
        const generatedPhotosCount =
          userImagesData?.generatedImages ||
          userImagesData?.images?.filter((img: any) => img.isGenerated)?.length ||
          0;

        this.setState({ generatedPhotosCount });
      }
    } catch (error) {
      console.error('Failed to refresh generated photos count:', error);
    }
  }

  /**
   * Clean image URL to remove fragments and cache-busting artifacts
   */
  private cleanImageUrl(url: string): string {
    try {
      const cleanUrl = url.split('#')[0].split('?')[0];

      if (!cleanUrl.startsWith('http') && !cleanUrl.startsWith('/')) {
        return '/' + cleanUrl;
      }

      return cleanUrl;
    } catch (error) {
      console.warn('Failed to clean image URL:', url, error);
      return url;
    }
  }

  /**
   * Public method for manual validation (debug purposes)
   */
  async validateCurrentImages(): Promise<void> {
    const currentState = this.getState();
    const images = currentState.uploadedImageThumbnails;

    if (images.length === 0) {
      return;
    }
    const result = await this.validateAndCleanupImages(images, false);

    if (result.removedCount > 0) {
      this.updateStateWithValidatedImages(result);

      const message = result.repairTriggered
        ? `Validated ${images.length} images. Removed ${result.removedCount} broken references and repaired database.`
        : `Validated ${images.length} images. Removed ${result.removedCount} broken references.`;

      this.showInfo(
        result.repairTriggered ? 'Validation & Repair Complete' : 'Image Validation Complete',
        message
      );
    } else {
      this.setState({
        imagesValidated: true,
        lastValidationTime: Date.now(),
      });

      this.showSuccess('All Images Valid', 'All uploaded images are accessible and valid.');
    }
  }

  /**
   * Invalidate images cache and refresh
   */
  invalidateAndRefresh(): void {
    this._fileUploadService.invalidateUserImagesCache();
    this.invalidateCache(this.CACHE_KEY);
    this.loadUserImages(true);
  }

  /**
   * Force refresh implementation
   */
  forceRefresh(): void {
    this.forceRefreshCache(this.CACHE_KEY);
    this._imageValidation.clearCache();

    this.setState({
      imagesValidated: false,
      lastValidationTime: 0,
    });

    this.loadUserImages(true);
  }
}

import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';

export interface ImageValidationResult {
  isValid: boolean;
  status: number | null;
  error?: string;
  url: string;
  repairSuggested?: boolean;
}

export interface ImageValidationSummary {
  validUrls: string[];
  invalidUrls: string[];
  results: ImageValidationResult[];
  repairSuggested: boolean;
  notFoundCount: number;
}

@Injectable({
  providedIn: 'root',
})
export class ImageValidationService {
  private validationCache = new Map<string, ImageValidationResult>();
  private readonly CACHE_TTL = 5 * 60 * 1000; // 5 minutes
  private readonly REQUEST_TIMEOUT = 10000; // 10 seconds
  private readonly FIRST_LOAD_DELAY = 2000; // 2 seconds delay for first load
  private isFirstLoad = true;

  constructor() {}

  /**
   * Validates if an image URL is accessible and returns a valid image
   * Uses HTTP HEAD request to check without downloading the full image
   * Defers validation on first load to improve performance
   */
  async validateImageUrl(url: string, skipFirstLoadDelay = false): Promise<ImageValidationResult> {
    // Fix: Convert absolute frontend URLs to relative paths for proxy routing
    const correctedUrl = this.correctImageUrl(url);

    // Skip validation for relative URLs (assume they're valid to avoid network calls)
    if (this.shouldSkipValidation(correctedUrl)) {
      return {
        isValid: true,
        status: 200,
        url: correctedUrl,
      };
    }

    // Check cache first
    const cached = this.validationCache.get(correctedUrl);
    if (cached && this.isCacheValid(correctedUrl)) {
      return cached;
    }

    // Defer validation on first load for performance
    if (this.isFirstLoad && !skipFirstLoadDelay) {
      setTimeout(() => this.validateImageUrl(correctedUrl, true), this.FIRST_LOAD_DELAY);
      this.isFirstLoad = false;
      // Return optimistic result for first load
      return {
        isValid: true,
        status: 200,
        url: correctedUrl,
      };
    }

    try {
      // Use HEAD request to check if image exists without downloading it
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), this.REQUEST_TIMEOUT);

      const response = await fetch(correctedUrl, {
        method: 'HEAD',
        signal: controller.signal,
        // Add credentials if needed for authenticated endpoints
        credentials: 'include',
      });

      clearTimeout(timeoutId);

      const result: ImageValidationResult = {
        isValid: response.ok,
        status: response.status,
        url: correctedUrl,
      };

      if (!response.ok) {
        result.error = `HTTP ${response.status}: ${response.statusText}`;
        // Suggest repair for 404s (orphaned database records)
        result.repairSuggested = response.status === 404;
      }

      // Cache the result
      this.cacheResult(correctedUrl, result);

      return result;
    } catch (error: any) {
      console.warn(`❌ Image validation failed for ${correctedUrl}:`, error);

      const result: ImageValidationResult = {
        isValid: false,
        status: null,
        error: error.name === 'AbortError' ? 'Timeout' : error.message,
        url: correctedUrl,
      };

      // Cache failed results for a shorter time to allow retries
      this.cacheResult(correctedUrl, result, 30000); // 30 seconds for failures

      return result;
    }
  }

  /**
   * Validates multiple image URLs in parallel
   * Returns detailed validation summary including repair suggestions
   */
  async validateImageUrls(urls: string[]): Promise<ImageValidationSummary> {
    const validationPromises = urls.map(url => this.validateImageUrl(url));
    const results = await Promise.all(validationPromises);

    const validUrls = results.filter(r => r.isValid).map(r => r.url);
    const invalidUrls = results.filter(r => !r.isValid).map(r => r.url);
    const notFoundCount = results.filter(r => r.status === 404).length;
    const repairSuggested = results.some(r => r.repairSuggested);

    console.log(
      `✅ Validation complete: ${validUrls.length} valid, ${invalidUrls.length} invalid${repairSuggested ? ', repair suggested' : ''}`
    );

    return {
      validUrls,
      invalidUrls,
      results,
      repairSuggested,
      notFoundCount,
    };
  }

  /**
   * Checks if a specific URL returns a 404 error
   */
  async isImageNotFound(url: string): Promise<boolean> {
    const result = await this.validateImageUrl(url);
    return result.status === 404;
  }

  /**
   * Filters an array of image objects, removing those with invalid URLs
   */
  async filterValidImages<T extends { url: string }>(
    images: T[]
  ): Promise<{
    validImages: T[];
    invalidImages: T[];
    removedCount: number;
    repairSuggested: boolean;
    notFoundCount: number;
  }> {
    if (images.length === 0) {
      return {
        validImages: [],
        invalidImages: [],
        removedCount: 0,
        repairSuggested: false,
        notFoundCount: 0,
      };
    }

    const urls = images.map(img => img.url);
    const validation = await this.validateImageUrls(urls);

    const validImages = images.filter(img => validation.validUrls.includes(img.url));
    const invalidImages = images.filter(img => validation.invalidUrls.includes(img.url));

    return {
      validImages,
      invalidImages,
      removedCount: invalidImages.length,
      repairSuggested: validation.repairSuggested,
      notFoundCount: validation.notFoundCount,
    };
  }

  private cacheResult(url: string, result: ImageValidationResult, ttl: number = this.CACHE_TTL) {
    this.validationCache.set(url, {
      ...result,
      // Add timestamp for TTL
      timestamp: Date.now(),
    } as any);

    // Set cleanup timer
    setTimeout(() => {
      this.validationCache.delete(url);
    }, ttl);
  }

  private isCacheValid(url: string): boolean {
    const cached = this.validationCache.get(url) as any;
    if (!cached) {
      return false;
    }

    const age = Date.now() - (cached.timestamp || 0);
    return age < this.CACHE_TTL;
  }

  /**
   * Clears the validation cache
   */
  clearCache() {
    this.validationCache.clear();
  }

  /**
   * Gets cache stats for debugging
   */
  getCacheStats() {
    return {
      size: this.validationCache.size,
      entries: Array.from(this.validationCache.keys()),
    };
  }

  /**
   * Validates images progressively with batching and delays
   * Improves first-load performance by spreading validation requests
   */
  async validateImageUrlsProgressive(
    urls: string[],
    batchSize = 3,
    delayMs = 500
  ): Promise<ImageValidationSummary> {
    console.log(
      `🔍 Progressive validation of ${urls.length} URLs (batch: ${batchSize}, delay: ${delayMs}ms)`
    );

    const results: ImageValidationResult[] = [];

    // Process URLs in batches with delays
    for (let i = 0; i < urls.length; i += batchSize) {
      const batch = urls.slice(i, i + batchSize);

      // Add delay between batches (except first batch)
      if (i > 0) {
        await new Promise(resolve => setTimeout(resolve, delayMs));
      }

      const batchPromises = batch.map(url => this.validateImageUrl(url, true));
      const batchResults = await Promise.all(batchPromises);
      results.push(...batchResults);
    }

    // Compile summary
    const validUrls = results.filter(r => r.isValid).map(r => r.url);
    const invalidUrls = results.filter(r => !r.isValid).map(r => r.url);
    const notFoundCount = results.filter(r => r.status === 404).length;
    const repairSuggested = results.some(r => r.repairSuggested);

    console.log(
      `✅ Progressive validation complete: ${validUrls.length} valid, ${invalidUrls.length} invalid`
    );

    return {
      validUrls,
      invalidUrls,
      results,
      repairSuggested,
      notFoundCount,
    };
  }

  /**
   * Determines if validation should be skipped for certain URL patterns
   * Skips validation for relative URLs and known-good patterns to improve performance
   */
  private shouldSkipValidation(url: string): boolean {
    if (!url) {
      return true;
    }

    // Skip validation for relative URLs (they go through proxy)
    if (
      url.startsWith('/uploads/') ||
      url.startsWith('/generated/') ||
      url.startsWith('/style-previews/')
    ) {
      return true;
    }

    // Skip validation for localhost URLs (development)
    if (url.includes('localhost:')) {
      return true;
    }

    return false;
  }

  /**
   * Corrects absolute frontend URLs to relative paths for proper proxy routing
   * Fixes the architectural issue where frontend URLs don't route through the backend
   */
  private correctImageUrl(url: string): string {
    if (!url) {
      return url;
    }

    // If it's already a relative path, keep it as is
    if (url.startsWith('/')) {
      return url;
    }

    // Fix absolute frontend ngrok URLs to relative paths
    if (url.includes('awlocaldev.ngrok.app/uploads/')) {
      const path = url.substring(url.indexOf('/uploads/'));
      console.log(`🔧 Correcting frontend URL to relative path: ${url} → ${path}`);
      return path;
    }

    // Fix absolute frontend ngrok URLs for other static paths
    if (url.includes('awlocaldev.ngrok.app/generated/')) {
      const path = url.substring(url.indexOf('/generated/'));
      console.log(`🔧 Correcting frontend URL to relative path: ${url} → ${path}`);
      return path;
    }

    // Fix localhost URLs to relative paths
    if (url.includes('localhost:4200/uploads/')) {
      const path = url.substring(url.indexOf('/uploads/'));
      console.log(`🔧 Correcting localhost URL to relative path: ${url} → ${path}`);
      return path;
    }

    if (url.includes('localhost:4200/generated/')) {
      const path = url.substring(url.indexOf('/generated/'));
      console.log(`🔧 Correcting localhost URL to relative path: ${url} → ${path}`);
      return path;
    }

    // Keep other URLs as is (backend URLs, external URLs, etc.)
    return url;
  }
}

