import { Injectable } from '@angular/core';
import { forkJoin, Observable } from 'rxjs';
import { ProfileService } from './profile.service';
import { FileUploadService } from './file-upload.service';
import { IModelStateService, ModelStatusInfo } from '../interfaces/service.interfaces';

@Injectable({
  providedIn: 'root',
})
export class ModelStateService implements IModelStateService {
  constructor(
    private profileService: ProfileService,
    private fileUploadService: FileUploadService
  ) {}

  /**
   * Run model discovery asynchronously without blocking the UI
   */
  runAsyncModelDiscovery(): void {
    this.profileService.discoverModels().subscribe({
      next: discoveryResult => {
        if (discoveryResult?.success && discoveryResult?.data?.ModelsAdded > 0) {
          // Update just the model status without reloading everything
          this.updateModelStatus();
        }
      },
      error: error => {
        console.error('Async model discovery failed:', error);
        // Don't show error to user - this is a background operation
      },
    });
  }

  /**
   * Update only the model status after discovery
   */
  updateModelStatus(): void {
    forkJoin({
      trainingStatus: this.fileUploadService.getTrainingStatus(),
      modelRequests: this.fileUploadService.getUserModelRequests(),
    }).subscribe({
      next: ({ trainingStatus, modelRequests }) => {
        const modelRequestsData = modelRequests.success ? modelRequests.data : null;

        let modelStatus = 'Not Started';

        // Re-check model status with updated data
        if (modelRequestsData?.hasTrainedModel && modelRequestsData?.latestTrainedModel) {
          modelStatus = 'Model Ready';
          // Emit this update to dashboard state service if needed
          this.notifyModelStatusUpdate(modelStatus, modelRequestsData.latestTrainedModel);
        } else {
          this.notifyModelStatusUpdate(modelStatus, null);
        }
      },
      error: error => {
        console.error('Failed to update model status:', error);
      },
    });
  }

  /**
   * Debug methods for console testing
   */
  async debugModelStatus(): Promise<any> {
    try {
      const debugResult = await this.fileUploadService.getDebugModelStatus().toPromise();

      const testResult = await this.fileUploadService.testModelCreationEndpoint().toPromise();

      const discoverResult = await this.fileUploadService.discoverUserModels().toPromise();

      const specificModelTest = await this.fileUploadService.testSpecificModel().toPromise();

      return {
        debug: debugResult,
        test: testResult,
        discover: discoverResult,
        specificModel: specificModelTest,
      };
    } catch (error) {
      console.error('🚨 Debug failed:', error);
      return { error };
    }
  }

  /**
   * Manual model discovery method
   */
  async triggerModelDiscovery(): Promise<any> {
    try {
      const discoveryResult = await this.profileService.discoverModels().toPromise();

      if (discoveryResult?.success && discoveryResult?.data?.ModelsAdded > 0) {
        this.updateModelStatus();
      } else {
      }

      return discoveryResult;
    } catch (error) {
      console.error('🚨 Manual model discovery failed:', error);
      return { success: false, error };
    }
  }

  /**
   * Check if model discovery is needed based on current state
   */
  isModelDiscoveryNeeded(
    hasTrainedModel: boolean,
    modelStatus: string,
    uploadedImages: number
  ): boolean {
    return modelStatus === 'Not Started' && uploadedImages > 0 && !hasTrainedModel;
  }

  /**
   * Get model status from model requests data
   */
  getModelStatusFromData(
    modelRequestsData: any,
    trainingStatus: any
  ): {
    modelStatus: string;
    hasTrainedModel: boolean;
    latestTrainedModel: any;
  } {
    let modelStatus = 'Not Started';
    let hasTrainedModel = false;
    let latestTrainedModel = null;

    // 🔍 ENHANCED DEBUG: Model status data analysis

    // Use ModelCreationRequest as single source of truth
    if (modelRequestsData?.hasTrainedModel && modelRequestsData?.latestTrainedModel) {
      hasTrainedModel = true;
      modelStatus = 'Model Ready';
      latestTrainedModel = modelRequestsData.latestTrainedModel;
    }
    // Check if we have pending/in-progress training
    else if (
      modelRequestsData?.allRequests?.some(
        (req: any) => req.status === 'creating' || req.status === 'pending'
      )
    ) {
      modelStatus = 'training';
    }
    // Default to training status or initial state
    else {
      modelStatus = trainingStatus?.status || 'Not Started';
    }

    return { modelStatus, hasTrainedModel, latestTrainedModel };
  }

  /**
   * Notify dashboard state service of model status updates
   * This would be implemented to communicate with DashboardStateService
   */
  private notifyModelStatusUpdate(modelStatus: string, latestTrainedModel: any): void {
    // This could emit an event or call a callback
    // For now, just log the update
  }
}

import { Injectable } from '@angular/core';
import { NavigationEnd, Router } from '@angular/router';
import { Location } from '@angular/common';
import { filter } from 'rxjs/operators';

@Injectable({
  providedIn: 'root',
})
export class NavigationService {
  private navigationHistory: string[] = [];
  private maxHistoryLength = 10;

  constructor(
    private router: Router,
    private location: Location
  ) {
    // Track navigation history
    this.router.events
      .pipe(filter(event => event instanceof NavigationEnd))
      .subscribe((event: NavigationEnd) => {
        this.addToHistory(event.url);
      });
  }

  private addToHistory(url: string): void {
    // Remove the current URL if it already exists to avoid duplicates
    const index = this.navigationHistory.indexOf(url);
    if (index > -1) {
      this.navigationHistory.splice(index, 1);
    }

    // Add to the beginning of the array
    this.navigationHistory.unshift(url);

    // Keep only the most recent entries
    if (this.navigationHistory.length > this.maxHistoryLength) {
      this.navigationHistory = this.navigationHistory.slice(0, this.maxHistoryLength);
    }
  }

  /**
   * Navigate to a route with enhanced UX
   */
  navigateTo(
    route: string | string[],
    options?: {
      queryParams?: any;
      fragment?: string;
      replaceUrl?: boolean;
    }
  ): Promise<boolean> {
    const navigationExtras = {
      queryParams: options?.queryParams,
      fragment: options?.fragment,
      replaceUrl: options?.replaceUrl || false,
    };

    if (typeof route === 'string') {
      return this.router.navigate([route], navigationExtras);
    } else {
      return this.router.navigate(route, navigationExtras);
    }
  }

  /**
   * Navigate back to the previous page or fallback route
   */
  goBack(fallbackRoute = '/'): void {
    if (this.navigationHistory.length > 1) {
      // Go to the previous page in our history
      const previousUrl = this.navigationHistory[1];
      this.router.navigateByUrl(previousUrl);
    } else if (window.history.length > 1) {
      // Use browser's back functionality
      this.location.back();
    } else {
      // Fallback to specified route
      this.router.navigate([fallbackRoute]);
    }
  }

  /**
   * Get the current navigation history
   */
  getHistory(): string[] {
    return [...this.navigationHistory];
  }

  /**
   * Check if we can go back
   */
  canGoBack(): boolean {
    return this.navigationHistory.length > 1 || window.history.length > 1;
  }

  /**
   * Navigate to home page
   */
  goHome(): Promise<boolean> {
    return this.navigateTo('/');
  }

  /**
   * Navigate to authentication routes
   */
  goToLogin(): Promise<boolean> {
    return this.navigateTo('/auth/login');
  }

  goToRegister(): Promise<boolean> {
    return this.navigateTo('/auth/register');
  }

  /**
   * Navigate to app routes (protected)
   */
  goToDashboard(): Promise<boolean> {
    return this.navigateTo('/app/dashboard');
  }

  goToGallery(): Promise<boolean> {
    return this.navigateTo('/app/gallery');
  }

  goToEnhance(): Promise<boolean> {
    return this.navigateTo('/app/enhance');
  }

  goToSettings(): Promise<boolean> {
    return this.navigateTo('/app/settings');
  }

  /**
   * Navigate to public pages
   */
  goToPricing(): Promise<boolean> {
    return this.navigateTo('/pricing');
  }

  goToFeatures(): Promise<boolean> {
    return this.navigateTo('/features');
  }

  goToExamples(): Promise<boolean> {
    return this.navigateTo('/examples');
  }

  goToHelp(): Promise<boolean> {
    return this.navigateTo('/help');
  }

  /**
   * Navigate to legal pages
   */
  goToPrivacy(): Promise<boolean> {
    return this.navigateTo('/legal/privacy');
  }

  goToTerms(): Promise<boolean> {
    return this.navigateTo('/legal/terms');
  }

  /**
   * Scroll to section with smooth animation
   */
  scrollToSection(sectionId: string, offset = 80): void {
    setTimeout(() => {
      const element = document.getElementById(sectionId);
      if (element) {
        const elementPosition = element.getBoundingClientRect().top;
        const offsetPosition = elementPosition + window.pageYOffset - offset;

        window.scrollTo({
          top: offsetPosition,
          behavior: 'smooth',
        });
      }
    }, 100);
  }

  /**
   * Navigate to landing page section
   */
  navigateToSection(
    section: 'features' | 'examples' | 'pricing' | 'testimonials' | 'faq'
  ): Promise<boolean> {
    return this.navigateTo('/', { fragment: section }).then(success => {
      if (success) {
        this.scrollToSection(section);
      }
      return success;
    });
  }

  /**
   * Get current route information
   */
  getCurrentRoute(): string {
    return this.router.url;
  }

  /**
   * Check if current route matches
   */
  isCurrentRoute(route: string): boolean {
    return this.router.url === route;
  }

  /**
   * Check if current route starts with given path
   */
  isRouteActive(routePath: string): boolean {
    return this.router.url.startsWith(routePath);
  }
}

import { Injectable, NgZone } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';

export interface Notification {
  id: string;
  type: 'success' | 'error' | 'warning' | 'info';
  title: string;
  message: string;
  duration?: number; // in milliseconds, 0 means permanent
  timestamp: Date;
}

@Injectable({
  providedIn: 'root'
})
export class NotificationService {
  private notificationsSubject = new BehaviorSubject<Notification[]>([]);
  public notifications$ = this.notificationsSubject.asObservable();

  constructor(private ngZone: NgZone) {}

  private generateId(): string {
    return Math.random().toString(36).substr(2, 9);
  }

  private addNotification(notification: Omit<Notification, 'id' | 'timestamp'>): string {
    const id = this.generateId();
    const newNotification: Notification = {
      ...notification,
      id,
      timestamp: new Date(),
      duration: notification.duration ?? 5000 // 5 seconds default
    };

    const currentNotifications = this.notificationsSubject.value;
    this.notificationsSubject.next([...currentNotifications, newNotification]);

    // Auto-remove notification after duration
    if (newNotification.duration && newNotification.duration > 0) {
      this.ngZone.runOutsideAngular(() => {
        setTimeout(() => {
          this.ngZone.run(() => {
            this.removeNotification(id);
          });
        }, newNotification.duration);
      });
    }

    return id;
  }

  success(title: string, message: string, duration?: number): string {
    return this.addNotification({
      type: 'success',
      title,
      message,
      duration
    });
  }

  error(title: string, message: string, duration?: number): string {
    return this.addNotification({
      type: 'error',
      title,
      message,
      duration: duration ?? 0 // Errors stay until manually dismissed
    });
  }

  warning(title: string, message: string, duration?: number): string {
    return this.addNotification({
      type: 'warning',
      title,
      message,
      duration
    });
  }

  info(title: string, message: string, duration?: number): string {
    return this.addNotification({
      type: 'info',
      title,
      message,
      duration
    });
  }

  removeNotification(id: string): void {
    const currentNotifications = this.notificationsSubject.value;
    const updatedNotifications = currentNotifications.filter(n => n.id !== id);
    this.notificationsSubject.next(updatedNotifications);
  }

  clearAll(): void {
    this.notificationsSubject.next([]);
  }

  // Convenience methods for common scenarios
  uploadSuccess(fileCount: number): string {
    return this.success(
      'Upload Successful',
      `Successfully uploaded ${fileCount} image${fileCount > 1 ? 's' : ''}.`
    );
  }

  uploadError(error: string): string {
    return this.error(
      'Upload Failed',
      error || 'Failed to upload images. Please try again.'
    );
  }

  generationSuccess(creditsRemaining?: number): string {
    const message = creditsRemaining !== undefined 
      ? `Image generated successfully! You have ${creditsRemaining} credits remaining.`
      : 'Image generated successfully!';

    return this.success('Generation Complete', message);
  }

  generationError(error: string): string {
    return this.error(
      'Generation Failed',
      error || 'Failed to generate image. Please try again.'
    );
  }

  creditsExhausted(): string {
    return this.warning(
      'No Credits Remaining',
      'You have no credits remaining. Credits reset weekly, or upgrade for unlimited generations.'
    );
  }

  profileUpdateSuccess(): string {
    return this.success(
      'Profile Updated',
      'Your profile has been successfully updated.'
    );
  }

  profileUpdateError(error: string): string {
    return this.error(
      'Profile Update Failed',
      error || 'Failed to update profile. Please try again.'
    );
  }
}

