      // Load Stripe only if not in simulation mode
      const publishableKey = 'pk_test_51PWTf5Rrx34A3nCfA5lS45Ayj5tS4aL2g3v4w5x6y7z8a9b0c1d2e3f4g5h6i7j8k9l0m';
